// ===== ARMADO INTELIGENTE DE EQUIPOS =====
// ===== Armar a mano: cada capitán con su equipo =====
// ===== ELEMENTOS: los equipos se llaman Fuego, Hielo y Aire (con su logo) =====
const ELEMS = ['Fuego 🔥', 'Hielo ❄️', 'Aire 🌪️'];
const teamName = (i) => ELEMS[i] || 'Equipo ' + String.fromCharCode(65 + i);
const elemKey = (name) => { const m = /fuego|hielo|aire/i.exec(name || ''); return m ? m[0].toLowerCase() : null; };
const ElemLogo = ({ name, size = 40 }) => {
  const k = elemKey(name);
  return k ? <img src={`./elementos/${k}.jpg`} alt={k} width={size} height={size} style={{ width: size, height: size }} className="rounded-lg shrink-0 bg-black object-cover" /> : null;
};

function Draft({ pool, onStartTri }) {
  const [open, setOpen] = useState(false);
  const [caps, setCaps] = useState(['', '', '']);
  const [asg, setAsg] = useState({});
  const L = ['A', 'B', 'C'];
  const nick = (id) => (pool.find((p) => p.id === id) || {}).nickname || '?';
  const setCap = (i, id) => { const c = [...caps]; c[i] = id; setCaps(c); setAsg((a) => { const n = { ...a }; delete n[id]; return n; }); };
  const teams = [0, 1, 2].map((i) => ({
    name: caps[i] ? `${teamName(i)} · ${nick(caps[i])}` : teamName(i), cap: caps[i],
    ids: caps[i] ? [caps[i], ...pool.filter((p) => asg[p.id] === i && !caps.includes(p.id)).map((p) => p.id)] : []
  }));
  const free = pool.filter((p) => !caps.includes(p.id));
  const ready = caps.every(Boolean);
  if (!open) return <button onClick={() => setOpen(true)} className="w-full py-2.5 rounded-xl text-xs font-black bg-slate-800 text-amber-400 border border-amber-500/40">👑 Armar a mano con capitanes</button>;
  return (
    <div className={card + ' space-y-3 enter'}>
      <div className="flex justify-between items-center"><b className="text-sm">👑 Armar con capitanes</b><button onClick={() => setOpen(false)} className="text-xs text-slate-400">Cerrar</button></div>
      <div className="grid grid-cols-3 gap-2">
        {[0, 1, 2].map((i) => (
          <label key={i} className="text-[11px] text-slate-400">Capitán {L[i]}
            <select className={inp + ' mt-1 !px-2'} value={caps[i]} onChange={(e) => setCap(i, e.target.value)}>
              <option value="">Elegir</option>
              {pool.filter((p) => p.id === caps[i] || !caps.includes(p.id)).map((p) => <option key={p.id} value={p.id}>{p.nickname}</option>)}
            </select>
          </label>
        ))}
      </div>
      {ready && free.length > 0 && (
        <div className="space-y-1.5">
          <p className="text-xs text-slate-400">Toca la letra del equipo de cada jugador ({free.filter((p) => asg[p.id] === undefined).length} sin equipo):</p>
          {free.map((p) => (
            <div key={p.id} className="flex items-center justify-between bg-slate-950 rounded-xl px-3 py-1.5">
              <span className="text-sm">{p.avatar} {p.nickname}</span>
              <span className="flex gap-1">{[0, 1, 2].map((i) => (
                <button key={i} onClick={() => setAsg((a) => { const n = { ...a }; if (n[p.id] === i) delete n[p.id]; else n[p.id] = i; return n; })} className={`w-8 h-7 rounded-lg text-xs font-black ${asg[p.id] === i ? 'bg-amber-500 text-slate-950' : 'bg-slate-800 text-slate-400'}`}>{L[i]}</button>
              ))}</span>
            </div>
          ))}
        </div>
      )}
      {ready && <div className="grid grid-cols-3 gap-2">{teams.map((t, i) => <div key={i} className="rounded-xl border border-slate-800 p-2 text-center"><div className="flex justify-center mb-1"><ElemLogo name={t.name} size={44} /></div><b className="text-xs">{t.name}</b><p className="text-[10px] text-slate-400">{t.ids.length} jugadores</p></div>)}</div>}
      <button disabled={!ready} onClick={() => onStartTri(teams)} className="btn-fire w-full py-2.5 rounded-xl text-xs font-black disabled:opacity-40">Iniciar triangular con estos equipos 🔥</button>
    </div>
  );
}

// ===== Triangular: el que gana se queda (nadie juega 3 partidos seguidos) =====
function Triangular({ tri, players, isAdmin }) {
  const [sa, setSa] = useState(0); const [sb, setSb] = useState(0); const [mvp, setMvp] = useState(''); const [busy, setBusy] = useState(false);
  if (!tri) return null;
  const T = tri.teams, games = tri.games || [], x = tri.cur[0], y = tri.cur[1], w = tri.wait, consec = tri.consec || [0, 0, 0];
  const st = T.map((t, i) => ({ i, name: t.name, pj: 0, g: 0, p: 0, sf: 0, sc: 0 }));
  games.forEach((g) => { const A = st[g.a], B = st[g.b]; A.pj++; B.pj++; A.sf += g.sa; A.sc += g.sb; B.sf += g.sb; B.sc += g.sa; if (g.sa > g.sb) { A.g++; B.p++; } else { B.g++; A.p++; } });
  const table = [...st].sort((p, q) => q.g - p.g || (q.sf - q.sc) - (p.sf - p.sc) || q.sf - p.sf);
  const opts = [...T[x].ids, ...T[y].ids].map((id) => players.find((p) => p.id === id)).filter(Boolean);
  const save = async () => {
    if (sa === sb) return alert('No puede haber empate: un equipo debe ganar más sets.');
    setBusy(true);
    try {
      const win = sa > sb ? x : y, lose = sa > sb ? y : x, ws = Math.max(sa, sb);
      const c = [...consec]; c[x] += 1; c[y] += 1;
      let cur, wait;
      if (c[win] >= tri.max) { cur = [lose, w]; wait = win; } else { cur = [win, w]; wait = lose; }
      c[wait] = 0;
      const b = db.batch();
      T[win].ids.filter((id) => !isGuest(id)).forEach((id) => b.update(db.collection('players').doc(id), { matchesWon: FV.increment(1), setsWon: FV.increment(ws) }));
      T[lose].ids.filter((id) => !isGuest(id)).forEach((id) => b.update(db.collection('players').doc(id), { matchesLost: FV.increment(1) }));
      if (mvp && !isGuest(mvp)) b.update(db.collection('players').doc(mvp), { mvpCount: FV.increment(1) });
      b.set(db.collection('matches').doc(), { teamA: T[x].ids, teamB: T[y].ids, scoreA: sa, scoreB: sb, mvp, createdAt: Date.now() });
      b.update(db.collection('triangulars').doc(tri.id), { games: FV.arrayUnion({ a: x, b: y, sa, sb, at: Date.now() }), cur, wait, consec: c });
      await b.commit();
      setSa(0); setSb(0); setMvp('');
    } catch (e) { alert('No se pudo guardar: ' + e.message); }
    setBusy(false);
  };
  const finish = async () => {
    if (!confirm('¿Terminar el triangular y publicar la tabla final en el muro?')) return;
    const lines = table.map((r, k) => `${k + 1}. ${r.name}: ${r.g} G / ${r.p} P (sets ${r.sf}-${r.sc})`).join('\n');
    await db.collection('posts').add({ authorId: 'bot', authorName: 'IceFire', nick: 'arbitro', avatar: '🏆', content: `🏆 Triangular terminado (${games.length} partidos)\n${lines}\n🔥 Campeón: ${table[0].name}`, badge: '🏆 Triangular', likes: [], comments: [], createdAt: Date.now() });
    await db.collection('triangulars').doc(tri.id).update({ active: false });
  };
  const box = (i) => (
    <div className="rounded-xl border border-amber-500/40 bg-slate-950 p-2">
      <div className="flex justify-center mb-1"><ElemLogo name={T[i].name} size={52} /></div>
      <b className="text-sm">{T[i].name}</b>
      {T[i].cap && <p className="text-[10px] text-amber-400">👑 {(players.find((p) => p.id === T[i].cap) || {}).nickname}</p>}
      <p className="text-[10px] text-slate-400">{T[i].ids.map((id) => (players.find((p) => p.id === id) || {}).nickname || (isGuest(id) ? guestName(id) + ' (inv.)' : null)).filter(Boolean).join(', ')}</p>
      <p className="text-[10px] mt-1 text-amber-400 font-bold">{consec[i] + 1 >= tri.max ? 'Si gana, descansa' : 'Si gana, se queda'}</p>
    </div>
  );
  return (
    <section className={card + ' mb-4 space-y-3 enter'}>
      <div className="flex items-center justify-between"><b>🔥 Triangular en vivo</b><span className="text-xs text-slate-400">{games.length} partidos</span></div>
      <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-2 text-center">{box(x)}<span className="font-black text-amber-400">VS</span>{box(y)}</div>
      <p className="text-xs text-center text-slate-400">⏳ Espera: <b className="text-amber-400">{T[w].name}</b> · nadie juega 3 partidos seguidos</p>
      {isAdmin && (
        <div className="space-y-2 border-t border-slate-800 pt-3">
          <div className="grid grid-cols-2 gap-2">
            <label className="text-xs text-slate-400">Sets {T[x].name}<input type="number" min="0" max="9" className={inp + ' mt-1 text-center'} value={sa} onChange={(e) => setSa(+e.target.value || 0)} /></label>
            <label className="text-xs text-slate-400">Sets {T[y].name}<input type="number" min="0" max="9" className={inp + ' mt-1 text-center'} value={sb} onChange={(e) => setSb(+e.target.value || 0)} /></label>
          </div>
          <select className={inp} value={mvp} onChange={(e) => setMvp(e.target.value)}><option value="">⭐ MVP del partido (opcional)</option>{opts.map((p) => <option key={p.id} value={p.id}>{p.nickname}</option>)}</select>
          <div className="flex gap-2">
            <button disabled={busy} onClick={save} className="btn-fire flex-1 py-2.5 rounded-xl text-xs font-black disabled:opacity-50">{busy ? 'Guardando...' : 'Guardar partido y pasar al siguiente'}</button>
            <button onClick={finish} className="px-3 py-2.5 rounded-xl text-xs font-bold bg-slate-800 text-slate-300">Terminar</button>
          </div>
        </div>
      )}
      <div className="border-t border-slate-800 pt-3">
        <div className="grid grid-cols-[1fr_repeat(4,2rem)] gap-1 text-[11px] text-slate-500 font-bold px-1"><span>Equipo</span><span className="text-center">PJ</span><span className="text-center">G</span><span className="text-center">P</span><span className="text-center">Sets</span></div>
        {table.map((r, k) => (
          <div key={r.i} className={`grid grid-cols-[1fr_repeat(4,2rem)] gap-1 text-xs px-1 py-1.5 rounded-lg ${k === 0 && games.length ? 'bg-amber-500/10' : ''}`}>
            <span className="font-bold flex items-center gap-1.5">{k === 0 && games.length ? '👑 ' : ''}<ElemLogo name={r.name} size={20} />{r.name}</span><span className="text-center">{r.pj}</span><span className="text-center text-emerald-400 font-bold">{r.g}</span><span className="text-center text-rose-400">{r.p}</span><span className="text-center">{r.sf}-{r.sc}</span>
          </div>
        ))}
      </div>
      {games.length > 0 && <p className="text-[11px] text-slate-500">Últimos: {games.slice(-3).reverse().map((g) => `${T[g.a].name} ${g.sa}-${g.sb} ${T[g.b].name}`).join(' · ')}</p>}
    </section>
  );
}

function Teams({ players, events, initialEv, onRegister, onStartTri, isAdmin }) {
  const [off, setOff] = useState([]);
  const [calib, setCalib] = useState(null);
  const upcoming = events.filter((e) => e.date && when(e) >= Date.now() - 6 * 36e5).sort((a, b) => when(a) - when(b));
  const [sel, setSel] = useState(initialEv || (upcoming[0] ? upcoming[0].id : 'all'));
  const ev = events.find((e) => e.id === sel);
  const opts = ev && !upcoming.find((e) => e.id === ev.id) ? [ev, ...upcoming] : upcoming;
  const base = ev ? effGoing(ev).slice(0, ev.cap || 12).map((id) => players.find((p) => p.id === id) || (isGuest(id) ? { id, nickname: guestName(id) + ' (inv.)', avatar: '🎟️', position: guestPosOf(ev, id) || 'invitado', skills: (ev.guestSk || {})[id] || {}, isGuest: true } : null)).filter(Boolean) : players;
  const waiting = ev ? Math.max(0, effGoing(ev).length - (ev.cap || 12)) : 0;

  const [n, setN] = useState(2);
  const [res, setRes] = useState(null);
  const [ok, setOk] = useState(false);
  const [man, setMan] = useState(false);
  const [autoWa, setAutoWa] = useState(true);
  const [asg, setAsg] = useState({});

  const pool = base.filter((p) => !off.includes(p.id));

  const gen = () => {
    const T = Array.from({ length: n }, (_, i) => ({
      name: teamName(i),
      pl: [],
      tot: 0
    }));

    // Reparto por posiciones para garantizar balance técnico
    ['armador', 'central', 'punta', 'opuesto', 'defensa'].forEach((pos) => {
      pool.filter((p) => p.position === pos)
        .sort((a, b) => ovr(b.skills) - ovr(a.skills))
        .forEach((p) => {
          T.sort((a, b) => 
            (a.pl.filter((x) => x.position === pos).length - b.pl.filter((x) => x.position === pos).length) ||
            (a.pl.length - b.pl.length) ||
            (a.tot - b.tot)
          );
          T[0].pl.push(p);
          T[0].tot += ovr(p.skills);
        });
    });

    // Invitados (sin posición): se reparten al final para igualar el número de jugadores
    pool.filter((p) => !['armador', 'central', 'punta', 'opuesto', 'defensa'].includes(p.position))
      .sort((a, b) => ovr(b.skills) - ovr(a.skills))
      .forEach((p) => {
        T.sort((a, b) => (a.pl.length - b.pl.length) || (a.tot - b.tot));
        T[0].pl.push(p);
        T[0].tot += ovr(p.skills);
      });

    const sorted = T.sort((a, b) => a.name.localeCompare(b.name));
    setRes(sorted);
    if (autoWa) sendTeams(sorted, true);
  };

  // Armado a mano: tú eliges en qué equipo va cada jugador
  const genMan = () => {
    const T = Array.from({ length: n }, (_, i) => ({
      name: teamName(i),
      pl: pool.filter((p) => asg[p.id] === i),
      tot: 0
    }));
    T.forEach((t) => { t.tot = t.pl.reduce((a, p) => a + ovr(p.skills), 0); });
    T.manual = true;
    setRes(T);
    if (autoWa) sendTeams(T, true);
  };

  // Texto del mensaje de equipos (R = lista de equipos)
  const teamText = (R) => {
    let t = '🔥❄️ *ICEFIRE · ' + (R.manual ? 'EQUIPOS' : 'EQUIPOS BALANCEADOS') + '* ❄️🔥\n🏐━━━━━━━━━━━━🏐\n';
    if (ev) t += `\n📅 *${ev.title}*\n🗓 ${fmtDay(ev)} · 🕗 ${fmtHour(ev)}${placeTxt(ev) ? `\n📍 ${placeTxt(ev)}` : ''}\n`;
    t += '\n';
    R.forEach((e, ti) => {
      const avg = (e.tot / (e.pl.length || 1)).toFixed(1);
      t += `${teamIcon(ti)} *${e.name.toUpperCase()}* (⭐ ${avg})\n`;
      e.pl.forEach((p, i) => {
        const badge = POS.find((x) => x.id === p.position)?.s || (p.isGuest ? 'INV' : 'JUG');
        t += `  ${numEmo(i + 1)} ${p.nickname} [${badge}]\n`;
      });
      t += '\n';
    });
    if (ev && ev.fee > 0) t += `💸 Si aún no pagaste: yapea S/ ${ev.fee} a ${YAPE_NAME} (${YAPE_NUM}) 💜 hasta el ${fmtDL(ev)}.\n`;
    if (ev) t += `⏱ Llegar tarde = multa de S/ ${lateFeeOf(ev)} al fondo del grupo 😅\n`;
    t += '⏰ Llegar 15 min antes para calentar y armar la cancha 💪\n\n🏆 Ranking y resultados: ' + SITE_URL + '\n¡A darlo todo! 🔥❄️🏐';
    return t;
  };

  const sendTeams = (R, sendWa) => {
    const full = teamText(R);
    if (navigator.clipboard) navigator.clipboard.writeText(full).catch(() => {});
    if (sendWa === true) waShare(full);
    setOk(true);
    setTimeout(() => setOk(false), 2500);
  };

  const copy = (sendWa) => sendTeams(res, sendWa);

  return (
    <div className="space-y-3">
      <div className={card + ' space-y-3'}>
        <div className="flex justify-between items-center">
          <p className="text-sm font-bold text-amber-400">{ev ? 'Convocados de la pichanga' : 'Selecciona quiénes vinieron hoy'} ({pool.length} activos)</p>
          <button onClick={() => setOff([])} className="text-xs text-slate-400 hover:text-slate-200 underline">Marcar todos</button>
        </div>

        <select className={inp} value={sel} onChange={(e) => { setSel(e.target.value); setOff([]); setRes(null); setAsg({}); }}>
          {opts.map((e) => <option key={e.id} value={e.id}>🏐 {e.title} · {e.date} {e.time} ({Math.min(effGoing(e).length, e.cap || 12)} convocados)</option>)}
          <option value="all">👥 Todos los jugadores (manual)</option>
        </select>
        {ev && waiting > 0 && <p className="text-[11px] text-amber-400">+{waiting} en lista de espera no entran a los equipos.</p>}
        {ev && base.length === 0 && <p className="text-xs text-slate-500">Nadie se ha anotado a esta pichanga todavía.</p>}

        <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 max-h-60 overflow-y-auto p-1">
          {base.map((p) => {
            const isInactive = off.includes(p.id);
            return (
              <button key={p.id} onClick={() => setOff(isInactive ? off.filter((x) => x !== p.id) : [...off, p.id])} className={`p-2 rounded-xl border text-xs text-left flex justify-between items-center transition ${isInactive ? 'bg-slate-950 border-slate-800 text-slate-500 opacity-50' : 'bg-amber-500/10 border-amber-500/40 text-slate-200'}`}>
                <span className="truncate">{p.avatar} {p.nickname}</span>
                <span className="text-[10px] font-mono text-amber-400 font-bold">{ovr(p.skills).toFixed(1)}⭐</span>
              </button>
            );
          })}
        </div>

        <div className="flex justify-between items-center pt-2 border-t border-slate-800">
          <div className="flex gap-1.5">
            {[2, 3].map((k) => (
              <button key={k} onClick={() => setN(k)} className={`px-3 py-1.5 rounded-xl text-xs font-bold transition ${n === k ? 'bg-amber-500 text-slate-950 font-black' : 'bg-slate-800 text-slate-400'}`}>
                {k} Equipos
              </button>
            ))}
          </div>
          <button onClick={gen} disabled={pool.length < n * 2} className="px-4 py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-black text-xs rounded-xl disabled:opacity-40 shadow transition">
            Balancear Equipos
          </button>
        </div>

        <label className="flex items-center gap-2 text-xs text-slate-300 cursor-pointer">
          <input type="checkbox" checked={autoWa} onChange={(e) => setAutoWa(e.target.checked)} className="accent-emerald-500" />
          📲 Abrir WhatsApp con los equipos apenas se creen
        </label>
        <button onClick={() => setMan(!man)} className="w-full py-2 rounded-xl text-xs font-black bg-slate-800 text-amber-400 border border-amber-500/40">
          {man ? 'Cerrar armado a mano' : '✋ Armar a mano (tú eliges quién va en cada equipo)'}
        </button>
        {man && (
          <div className="space-y-1.5 enter">
            <p className="text-xs text-slate-400">Toca la letra del equipo de cada jugador ({pool.filter((p) => !(asg[p.id] < n)).length} sin equipo). Usa los botones de arriba para elegir 2 o 3 equipos.</p>
            <div className="max-h-72 overflow-y-auto space-y-1.5 p-1">
              {pool.map((p) => (
                <div key={p.id} className="flex items-center justify-between gap-2 bg-slate-950 rounded-xl px-3 py-1.5">
                  <span className="text-sm truncate">{p.avatar} {p.nickname}</span>
                  <span className="flex gap-1 shrink-0">
                    {Array.from({ length: n }).map((_, i) => (
                      <button key={i} onClick={() => setAsg((a) => { const x = { ...a }; if (x[p.id] === i) delete x[p.id]; else x[p.id] = i; return x; })} className={`w-8 h-7 rounded-lg text-xs font-black ${asg[p.id] === i ? 'bg-amber-500 text-slate-950' : 'bg-slate-800 text-slate-400'}`}>{String.fromCharCode(65 + i)}</button>
                    ))}
                  </span>
                </div>
              ))}
            </div>
            <div className={`grid gap-2 ${n === 3 ? 'grid-cols-3' : 'grid-cols-2'}`}>
              {Array.from({ length: n }).map((_, i) => (
                <div key={i} className="rounded-xl border border-slate-800 p-2 text-center">
                  <b className="text-xs">Equipo {String.fromCharCode(65 + i)}</b>
                  <p className="text-[10px] text-slate-400">{pool.filter((p) => asg[p.id] === i).length} jugadores</p>
                </div>
              ))}
            </div>
            <button onClick={genMan} disabled={Array.from({ length: n }).some((_, i) => !pool.some((p) => asg[p.id] === i))} className="w-full py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-black text-xs rounded-xl disabled:opacity-40 shadow transition">
              Usar estos equipos
            </button>
          </div>
        )}
      </div>

      {isAdmin && onStartTri && <Draft pool={pool} onStartTri={onStartTri} />}

      {res && (
        <div className="space-y-3 enter">
          <div className="grid sm:grid-cols-2 gap-3">
            {res.map((e) => (
              <div key={e.name} className={card + ' !p-0 overflow-hidden'}>
                <div className="p-3 bg-slate-800/80 flex justify-between items-center border-b border-slate-700/50">
                  <span className="flex items-center gap-2"><ElemLogo name={e.name} size={44} /><b className="text-amber-400">{e.name}</b></span>
                  <span className="text-xs font-mono text-amber-300 font-bold">⭐ Prom: {(e.tot / (e.pl.length || 1)).toFixed(1)}</span>
                </div>
                <div className="p-3 divide-y divide-slate-800/80">
                  {e.pl.map((p) => (
                    <div key={p.id} className="py-1.5 flex justify-between items-center text-sm">
                      <span className="text-slate-200">{p.avatar} {p.nickname}</span>
                      {isAdmin && <button title="Editar score" onClick={() => setCalib(p)} className="ml-auto mr-2 text-[11px] font-mono font-bold text-amber-400 bg-slate-800 rounded-lg px-1.5 py-0.5">⭐ {ovr(p.skills).toFixed(1)}</button>}
                      {p.isGuest && !POS.some((x) => x.id === p.position) ? <span className="text-[10px] font-bold px-1.5 py-0.5 rounded border bg-slate-700/40 text-slate-300 border-slate-600">INV</span> : <Badge id={p.position} />}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>

          {isAdmin && <p className="text-[11px] text-slate-400">Toca el ⭐ de un jugador para ajustar su score. Luego vuelve a generar los equipos para rebalancear.</p>}
          {calib && <SkillEditor player={calib} onClose={() => setCalib(null)} onSave={calib.isGuest && ev ? (skills, pos) => db.collection('events').doc(ev.id).update({ ['guestSk.' + calib.id]: skills, ...(pos ? { ['guestPos.' + calib.id]: pos } : {}) }) : undefined} />}
          <div className="flex flex-wrap gap-2">
            <button onClick={() => copy(true)} className="flex-1 min-w-[150px] py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-xs font-bold transition shadow">
              Enviar al grupo de WhatsApp 💬
            </button>
            <button onClick={() => copy(false)} className="flex-1 min-w-[150px] py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-xl text-xs font-bold transition shadow">
              {ok ? '¡Copiado! ✅' : 'Copiar texto 📋'}
            </button>
            {isAdmin && res.length >= 2 && res.flatMap((t1, i) => res.slice(i + 1).map((t2) => (
              <button key={t1.name + t2.name} onClick={() => onRegister(t1.pl.map((p) => p.id), t2.pl.map((p) => p.id))} className="flex-1 min-w-[150px] py-2.5 btn-fire rounded-xl text-xs font-black shadow">
                Registrar {t1.name} vs {t2.name} 🏆
              </button>
            )))}
            {isAdmin && res.length === 3 && onStartTri && (
              <button onClick={() => onStartTri(res.map((t) => ({ name: t.name, ids: t.pl.map((p) => p.id) })))} className="w-full py-2.5 bg-amber-500 text-slate-950 rounded-xl text-xs font-black shadow">
                Iniciar triangular: el que gana se queda 🔥
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// ===== CONVOCATORIA DE PICHANGA & CONTROL DE PAGOS =====
const MS = ['ENE', 'FEB', 'MAR', 'ABR', 'MAY', 'JUN', 'JUL', 'AGO', 'SET', 'OCT', 'NOV', 'DIC'];
const when = (e) => new Date(`${e.date}T${e.time || '00:00'}`);
// Plazo de pago: 12 horas antes de la pichanga. Pasado el plazo, quien no pagó (ni avisó su pago) pierde el cupo.
const PAY_H = 12;
const payDeadline = (e) => when(e).getTime() - (e.payHours || PAY_H) * 36e5;
const payClosed = () => false;
// Invitados sin cuenta (los anota un admin)
const isGuest = (id) => String(id).startsWith('guest:');
const guestName = (id) => String(id).slice(6);
const addGuest = async (ev, name, pos) => {
  const clean = String(name || '').trim().replace(/[.\[\]*~/`]/g, '').slice(0, 30);
  if (!clean) return false;
  if (!pos) { alert('Elige la posición del invitado'); return false; }
  const id = 'guest:' + clean;
  if ((ev.going || []).includes(id)) { alert('Ese nombre ya está en la lista'); return false; }
  try { await db.collection('events').doc(ev.id).update({ going: FV.arrayUnion(id), ['guestPos.' + id]: pos }); return true; }
  catch (e) { console.error(e); alert('No se pudo agregar al invitado.'); return false; }
};
// Cambiar la posición de un invitado ya anotado (solo admins)
const setGuestPos = (ev, id, pos) => db.collection('events').doc(ev.id).update({ ['guestPos.' + id]: pos }).catch((e) => { console.error(e); alert('No se pudo cambiar la posición.'); });
const guestPosOf = (ev, id) => (ev.guestPos || {})[id] || '';
// Cambiar la cuota de una pichanga (solo admins)
const editFee = (ev) => {
  const v = prompt('Nueva cuota por persona (S/). Pon 0 si es gratis:', ev.fee || 0);
  if (v === null) return;
  const n = Math.round(parseFloat(String(v).replace(',', '.')) * 100) / 100;
  if (!isFinite(n) || n < 0 || n > 500) return alert('Escribe un número válido, por ejemplo 15 o 12.5');
  db.collection('events').doc(ev.id).update({ fee: n }).catch((e) => { console.error(e); alert('No se pudo cambiar la cuota.'); });
};
const removeGuest = (ev, id) => db.collection('events').doc(ev.id).update({ going: FV.arrayRemove(id), ['guestPos.' + id]: FV.delete() }).catch(console.error);
const removeFromEvent = (ev, id, name) => {
  if (isGuest(id)) return removeGuest(ev, id);
  if (!confirm('¿Sacar a ' + (name || 'este jugador') + ' de la pichanga?')) return;
  return db.collection('events').doc(ev.id).update({ going: FV.arrayRemove(id), ['paid.' + id]: FV.delete() }).catch((e) => alert('No se pudo sacar: ' + e.message));
};
const effGoing = (e) => { const g = e.going || []; return payClosed(e) ? g.filter((id) => (e.paid || {})[id]) : g; };
// Multa por llegar tarde: va al fondo del grupo
const LATE_FEE = 2;
const lateFeeOf = (e) => e.lateFee || LATE_FEE;
const fundOf = (evs, uid) => {
  let paid = 0, due = 0, mine = 0;
  evs.forEach((e) => Object.keys(e.late || {}).forEach((id) => {
    const ok = (e.latePaid || {})[id] === 'ok';
    if (ok) paid += lateFeeOf(e); else { due += lateFeeOf(e); if (id === uid) mine += lateFeeOf(e); }
  }));
  return { paid, due, mine };
};
const fmtDL = (e) => new Date(payDeadline(e)).toLocaleString('es-PE', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
const left = (e) => {
  // Compara días del calendario (no horas), para que una pichanga de hoy no diga "mañana"
  const a = new Date(); a.setHours(0, 0, 0, 0);
  const b = when(e); b.setHours(0, 0, 0, 0);
  const d = Math.round((b - a) / 864e5);
  return d < 0 ? 'Ya pasó' : d === 0 ? '¡Es hoy!' : d === 1 ? 'Es mañana' : `Faltan ${d} días`;
};

// Fecha y hora bonitas para los mensajes: "Sábado 8 de noviembre · 8:00 p. m."
const fmtDay = (ev) => { const t = when(ev).toLocaleDateString('es-PE', { weekday: 'long', day: 'numeric', month: 'long' }); return t.charAt(0).toUpperCase() + t.slice(1); };
const fmtHour = (ev) => when(ev).toLocaleTimeString('es-PE', { hour: 'numeric', minute: '2-digit' });
// Números con emoji (1️⃣ 2️⃣ ... 🔟) y fuego/hielo alternados para las listas
const numEmo = (n) => (n === 10 ? '🔟' : String(n).split('').map((d) => d + '\uFE0F\u20E3').join(''));
const fireIce = (i) => (i % 2 === 0 ? '🔥' : '❄️');
const teamIcon = (i) => ['🔥', '❄️', '⚡'][i] || '🏐';
// Bloque de cuota + plazo de pago (12 h antes del partido). Solo si la pichanga tiene cuota.
const payLine = (ev) => ev.fee > 0
  ? `\n💰 Cuota: *S/ ${ev.fee}*\n💜 Yape a ${YAPE_NAME}: *${YAPE_NUM}*\n⏰ Paga hasta el *${fmtDL(ev)}* (${ev.payHours || PAY_H} h antes del partido) 🙏`
  : '\n🆓 Esta pichanga es gratis 🎉';
const placeLines = (ev) => {
  const pl = placeTxt(ev), mp = mapsOf(ev);
  return `${pl ? `\n📍 ${pl}` : ''}${mp ? `\n🗺 Cómo llegar: ${mp}` : ''}${!pl && !mp ? '\n📍 Lugar por confirmar 🤔' : ''}`;
};

const evText = (ev) => {
  const g = effGoing(ev), cap = ev.cap || 12, libres = Math.max(0, cap - g.length);
  return `🔥❄️ *${ev.title.toUpperCase()}* ❄️🔥\n🏐━━━━━━━━━━━━🏐\n🗓 ${fmtDay(ev)}\n🕗 ${fmtHour(ev)}${placeLines(ev)}${payLine(ev)}\n\n👥 ${Math.min(g.length, cap)}/${cap} confirmados ${libres > 0 ? `· 🎟️ quedan ${libres} cupos` : '· 🚫 lista llena'}\n\n💪 ¡Anótate en la web! 👇\n${evLink(ev.id)}`;
};

const evOpen = (ev) => '🚨🔥 *¡YA ESTÁ ABIERTA LA LISTA!* 🔥🚨\n🏐 ¡Anótate a la pichanga! 💪\n\n' + evText(ev);
const evSpots = (ev) => {
  const cap = ev.cap || 12, left = cap - effGoing(ev).length;
  const head = left > 0
    ? `⚠️🔥 *¡CUPOS LIMITADOS!* 🔥⚠️\n⏳ Quedan solo *${left}* de ${cap} lugares 🏐`
    : `🚫❄️ *¡LISTA LLENA!* ❄️🚫\n😮 Ya están los ${cap} cupos. ¡Aún puedes entrar a la lista de espera! 🏐`;
  return `${head}\n\n🔥 *${ev.title}* ❄️\n🗓 ${fmtDay(ev)} · 🕗 ${fmtHour(ev)}${placeLines(ev)}${payLine(ev)}\n\n${left > 0 ? '🏃 ¡Anótate antes de que se llene! 👇' : '⏳ Entra a la lista de espera 👇'}\n${evLink(ev.id)}`;
};

function Events({ me, events, players, isAdmin, focusId, onTeams, onProfile }) {
  const blank = { title: 'Pichanga de vóley', date: '', time: '20:00', place: '', maps: '', fee: '', cap: 12 };
  const [open, setOpen] = useState(false);
  const [f, setF] = useState(blank);
  const [created, setCreated] = useState(null);
  const [cp, setCp] = useState('');
  const copy = (key, text) => {
    if (navigator.clipboard) navigator.clipboard.writeText(text).catch(() => {});
    setCp(key); setTimeout(() => setCp(''), 2000);
  };

  useEffect(() => {
    if (!focusId) return;
    const t = setTimeout(() => { const el = document.getElementById('ev-' + focusId); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' }); }, 250);
    return () => clearTimeout(t);
  }, [focusId, events.length]);

  const byId = (id) => players.find((p) => p.id === id);

  const create = async (e) => {
    e.preventDefault(); if (!f.date) return;
    const data = {
      ...f,
      fee: +f.fee || 0,
      cap: +f.cap || 12,
      payTo: YAPE_TXT,
      createdBy: me.id,
      going: [me.id],
      paid: {},
      createdAt: Date.now()
    };
    const ref = await db.collection('events').add(data);

    await db.collection('posts').add({
      authorId: 'bot',
      authorName: 'IceFire Bot',
      nick: 'arbitro',
      avatar: '📅',
      content: `📅 ¡NUEVA PICHANGA CONVOCADA!\n\n🏐 ${f.title}\n🗓 Fecha: ${f.date} | 🕗 Hora: ${f.time}${placeTxt(data) ? `\n📍 Cancha: ${placeTxt(data)}` : ''}${mapsOf(data) ? `\n🗺 Google Maps: ${mapsOf(data)}` : ''}${+f.fee ? `\n💰 Cuota: S/ ${f.fee} por persona\n💜 Yape a ${YAPE_NAME}: ${YAPE_NUM}` : ''}\n\n🔥 Anótate aquí: ${evLink(ref.id)}`,
      badge: '📅 Convocatoria',
      likes: [],
      comments: [],
      createdAt: Date.now()
    });

    setCreated({ ...data, id: ref.id }); setF(blank); setOpen(false);
  };

  const toggle = (ev) => {
    if (!(ev.going || []).includes(me.id) && payClosed(ev)) return alert('El plazo de pago ya venció: las inscripciones de esta pichanga están cerradas.');
    db.collection('events').doc(ev.id).update({
      going: (ev.going || []).includes(me.id) ? FV.arrayRemove(me.id) : FV.arrayUnion(me.id)
    });
  };

  const setPaid = (ev, uid, v) => {
    db.collection('events').doc(ev.id).update({
      ['paid.' + uid]: v === null ? FV.delete() : v
    });
  };

  const toggleLate = (ev, uid) => {
    const on = !!(ev.late || {})[uid];
    db.collection('events').doc(ev.id).update(on ? { ['late.' + uid]: FV.delete(), ['latePaid.' + uid]: FV.delete() } : { ['late.' + uid]: true, ['att.' + uid]: true });
  };
  const toggleAtt = (ev, uid) => db.collection('events').doc(ev.id).update({ ['att.' + uid]: (ev.att || {})[uid] ? FV.delete() : true });
  const allAtt = (ev, ids) => db.collection('events').doc(ev.id).update(Object.fromEntries(ids.map((id) => ['att.' + id, true])));
  const setLatePaid = (ev, uid, v) => db.collection('events').doc(ev.id).update({ ['latePaid.' + uid]: v ? 'ok' : FV.delete() });

  const evPay = (ev) => {
    const pays = ev.paid || {};
    const pend = (ev.going || []).slice(0, ev.cap || 12).filter((id) => pays[id] !== 'ok').map((id) => ({ id, p: byId(id), st: pays[id] })).filter((x) => x.p || isGuest(x.id));
    if (!pend.length) return `✅🎉 *${ev.title}*\n¡Todos los convocados ya pagaron! Gracias equipo 🔥❄️🙌`;
    const vencido = Date.now() > payDeadline(ev);
    return `💸🔥 *RECORDATORIO DE PAGO* 🔥💸\n🏐 ${ev.title}\n🗓 ${fmtDay(ev)} · 🕗 ${fmtHour(ev)}\n\n💰 Cuota: *S/ ${ev.fee}*\n💜 Yape a ${YAPE_NAME}: *${YAPE_NUM}*\n${vencido ? '🚨 ¡El plazo ya venció! Yapea hoy mismo 🙏' : `⏰ Plazo: hasta el *${fmtDL(ev)}* (${ev.payHours || PAY_H} h antes) 🙏`}\n\n⏳ *Faltan pagar (${pend.length}):*\n${pend.map((x, i) => `${fireIce(i)} ${x.p ? x.p.nickname : guestName(x.id) + ' (inv.)'}${x.st === 'pending' ? ' ⏳ (avisó, por confirmar)' : ' 💸'}`).join('\n')}\n\n📲 Yapea y toca "Ya yapeé" en la web 👇\n${evLink(ev.id)}\n\n¡Gracias! 🙌🏐`;
  };

  const evList = (ev) => {
    const cap = ev.cap || 12, g = effGoing(ev);
    const nm = (id) => { const p = byId(id); return p ? p.nickname : isGuest(id) ? guestName(id) + ' (inv.)' : 'Jugador'; };
    const rows = Array.from({ length: cap }).map((_, i) => `${numEmo(i + 1)} ${g[i] ? fireIce(i) + ' ' + nm(g[i]) : '▫️ libre'}`);
    const wait = g.slice(cap).map((id, i) => `${numEmo(cap + i + 1)} ⏳ ${nm(id)}`);
    return `🏐 *${ev.title}* 🏐\n🗓 ${fmtDay(ev)} · 🕗 ${fmtHour(ev)}${placeTxt(ev) ? `\n📍 ${placeTxt(ev)}` : ''}\n\n🔥❄️ *LISTA (${Math.min(g.length, cap)}/${cap})* ❄️🔥\n${rows.join('\n')}${wait.length ? `\n\n⏳ *Lista de espera*\n${wait.join('\n')}` : ''}${ev.fee > 0 ? `\n\n💰 Cuota S/ ${ev.fee} · ⏰ paga hasta el ${fmtDL(ev)}` : ''}\n\n💪 ¡Anótate aquí! 👇\n${evLink(ev.id)}`;
  };

  // Aviso "Así será el juego de hoy": quiénes vienen, posiciones, formato y recordatorios
  const evToday = (ev, note) => {
    const cap = ev.cap || 12, g = effGoing(ev).slice(0, cap), n = g.length;
    const pad = (x) => String(x).padStart(2, '0'), d0 = new Date();
    const hoy = ev.date === `${d0.getFullYear()}-${pad(d0.getMonth() + 1)}-${pad(d0.getDate())}`;
    const nm = (id) => { const p = byId(id); return p ? p.nickname : isGuest(id) ? guestName(id) + ' (inv.)' : 'Jugador'; };
    const cnt = {};
    g.forEach((id) => { const p = byId(id); const pos = p ? p.position : guestPosOf(ev, id); if (pos) cnt[pos] = (cnt[pos] || 0) + 1; });
    const posTxt = POS.filter((x) => cnt[x.id]).map((x) => `${x.s} ${cnt[x.id]}`).join(' · ');
    const teamsN = n >= 15 ? 3 : 2, per = Math.floor(n / teamsN);
    const formato = n < 4 ? 'Faltan jugadores para armar equipos 😬' : teamsN === 3 ? `3 equipos de ${per} 🔥❄️⚡ · triangular: ¡el que gana se queda! 🏆` : `2 equipos de ${per} · 🔥 vs ❄️`;
    const pend = ev.fee > 0 ? g.filter((id) => (ev.paid || {})[id] !== 'ok').length : 0;
    return `🔥❄️ *${hoy ? '¡ASÍ SERÁ EL JUEGO DE HOY!' : '¡ASÍ SERÁ EL JUEGO!'}* ❄️🔥\n🏐━━━━━━━━━━━━🏐\n📅 *${ev.title}*\n🗓 ${hoy ? 'HOY · ' : ''}${fmtDay(ev)}\n🕗 ${fmtHour(ev)}${placeLines(ev)}\n\n👥 *Vamos ${n} jugadores:*\n${g.map((id, i) => `${numEmo(i + 1)} ${fireIce(i)} ${nm(id)}`).join('\n')}${posTxt ? `\n\n🎯 Posiciones: ${posTxt}` : ''}\n🏐 Formato: ${formato}${note ? `\n\n📝 *Nota:* ${note}` : ''}${pend > 0 ? `\n\n💸 Faltan ${pend} por pagar: yapea S/ ${ev.fee} a ${YAPE_NAME} (${YAPE_NUM}) 💜${Date.now() < payDeadline(ev) ? ` antes del ${fmtDL(ev)}` : ' hoy mismo 🙏'}` : ''}\n\n⏰ Llegar 15 min antes para calentar y armar la cancha 💪\n⏱ Llegar tarde = multa de S/ ${lateFeeOf(ev)} al fondo del grupo 😅\n💧 Lleven agua\n\n🔥 Lista y equipos en la web 👇\n${evLink(ev.id)}\n¡Nos vemos en la cancha! 🏐❄️🔥`;
  };

  const payYape = (ev) => {
    const msg = `Hola ${YAPE_NAME} 👋💜\nSoy ${me.nickname} (${me.name}). Ya yapeé *S/ ${ev.fee}* 💸 por la pichanga "${ev.title}" 🏐 del ${fmtDay(ev)}.\n¿Me confirmas el pago? 🙏\n\n🔗 Ver pichanga: ${evLink(ev.id)}`;
    waOpen(YAPE_WA, msg);
    if (pays_of(ev)[me.id] !== 'pending') setPaid(ev, me.id, 'pending');
  };
  const pays_of = (ev) => ev.paid || {};

  const remove = (ev) => confirm('¿Eliminar esta convocatoria?') && db.collection('events').doc(ev.id).delete();

  const renderEv = (ev, past) => {
    const d = when(ev), g = effGoing(ev), pays = ev.paid || {}, raw = ev.going || [], inRaw = raw.includes(me.id), iGo = g.includes(me.id);
    const canManage = isAdmin; // solo admins confirman pagos
    const full = g.length >= ev.cap, ok = g.filter((id) => pays[id] === 'ok').length, mine = pays[me.id];

    return (
      <article key={ev.id} id={'ev-' + ev.id} className={card + ' !p-0 overflow-hidden enter ' + (past ? 'opacity-60 ' : '') + (focusId === ev.id ? 'ring-2 ring-orange-500' : '')}>
        <div className="ev-hd p-4 flex items-center gap-4">
          <div className="datebox text-center bg-slate-950 border border-orange-500/40 rounded-2xl px-3.5 py-2">
            <div className="text-3xl leading-none">{d.getDate()}</div>
            <div className="text-xs text-amber-400 font-bold">{MS[d.getMonth()]}</div>
          </div>
          <div className="flex-1 min-w-0">
            <b className="block truncate text-base text-slate-100">{ev.title}</b>
            <p className="text-xs text-slate-400">🕗 {ev.time} · 📍 {placeTxt(ev) || (mapsOf(ev) ? 'Ver ubicación abajo' : 'Por definir')}</p>
            <p className="text-xs font-bold text-amber-400 mt-0.5">{left(ev)}</p>
          </div>
          {canManage && (
            <div className="flex items-center gap-1">
              {!past && <button title="Cambiar cuota" onClick={() => editFee(ev)} className="px-2 py-1 rounded-lg bg-amber-500/15 border border-amber-500/40 text-amber-400 text-xs font-bold">💰 {ev.fee > 0 ? 'S/ ' + ev.fee : 'Cuota'} ✏️</button>}
              <button title="Borrar" onClick={() => remove(ev)} className="text-slate-500 hover:text-rose-400 text-sm px-2">🗑️</button>
            </div>
          )}
        </div>

        <div className="p-4 space-y-3">
          <div>
            <div className="flex justify-between text-xs mb-1.5">
              <span className="flex items-center gap-2"><span><b>{Math.min(g.length, ev.cap)}</b>/{ev.cap} confirmados</span>
                {!past && (ev.cap - g.length <= 0 ? <span className="af-chip af-chip-full">Llena</span> : ev.cap - g.length <= 3 ? <span className="af-chip af-chip-warn">¡Solo {ev.cap - g.length} {ev.cap - g.length === 1 ? 'cupo' : 'cupos'}!</span> : <span className="af-chip af-chip-ok">{ev.cap - g.length} cupos libres</span>)}</span>
              {g.length > ev.cap && <span className="text-amber-400 font-bold">+{g.length - ev.cap} en lista de espera</span>}
            </div>
            <div className="h-2.5 rounded-full bg-slate-800 overflow-hidden">
              <div className="bar h-full rounded-full" style={{ width: Math.min(100, (g.length / ev.cap) * 100) + '%' }} />
            </div>
          </div>

          <div className="space-y-1.5">
            <p className="text-[11px] font-bold text-amber-400">📋 Lista de convocados</p>
            <div className="grid sm:grid-cols-2 gap-x-3 gap-y-1.5">
              {Array.from({ length: ev.cap || 12 }).map((_, i) => {
                const id = g[i], p = id ? byId(id) : null, st = id ? pays[id] : null;
                return id ? (
                  <div key={i} onClick={() => p && onProfile && onProfile(p.id)} className="slot slot-on">
                    <span className="slot-n">{i + 1}</span>
                    <span>{fireIce(i)}</span>
                    {p && <Av p={p} size="w-6 h-6" text="text-sm" />}
                    <b className="truncate">{p ? p.nickname : isGuest(id) ? guestName(id) + ' (inv.)' : 'Jugador'}</b>
                    {isGuest(id) && (isAdmin
                      ? <select value={guestPosOf(ev, id)} onClick={(e) => e.stopPropagation()} onChange={(e) => setGuestPos(ev, id, e.target.value)} className="text-[10px] bg-slate-900 border border-slate-700 rounded px-1 py-0.5 text-slate-200">
                          <option value="">¿Pos?</option>
                          {POS.map((pos) => <option key={pos.id} value={pos.id}>{pos.s}</option>)}
                        </select>
                      : guestPosOf(ev, id) && <Badge id={guestPosOf(ev, id)} />)}
                    {ev.fee > 0 && <span className="ml-auto text-xs">{st === 'ok' ? '✅' : st === 'pending' ? '⏳' : ''}</span>}
                    {isAdmin && <button title="Sacar de la pichanga" onClick={(e) => { e.stopPropagation(); removeFromEvent(ev, id, p && p.nickname); }} className="ml-1 text-rose-400 text-xs font-bold">✕</button>}
                  </div>
                ) : (
                  <div key={i} className="slot slot-off"><span className="slot-n">{i + 1}</span><span>▫️</span><span>libre</span></div>
                );
              })}
            </div>
            {g.length > (ev.cap || 12) && (
              <div className="pt-1.5 space-y-1.5">
                <p className="text-[11px] font-bold text-slate-400">⏳ Lista de espera</p>
                <div className="grid sm:grid-cols-2 gap-x-3 gap-y-1.5">
                  {g.slice(ev.cap || 12).map((id, i) => {
                    const p = byId(id);
                    return (
                      <div key={id} onClick={() => p && onProfile && onProfile(p.id)} className="slot slot-wait cursor-pointer">
                        <span className="slot-n">{(ev.cap || 12) + i + 1}</span>
                        <span>⏳</span>
                        {p && <Av p={p} size="w-6 h-6" text="text-sm" />}
                        <b className="truncate">{p ? p.nickname : isGuest(id) ? guestName(id) + ' (inv.)' : 'Jugador'}</b>
                        {isAdmin && <button title="Sacar de la pichanga" onClick={(e) => { e.stopPropagation(); removeFromEvent(ev, id, p && p.nickname); }} className="ml-auto text-rose-400 text-xs font-bold">✕</button>}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>

          {ev.late && ev.late[me.id] && (
            <p className={`text-xs rounded-xl p-2 font-bold text-center border ${(ev.latePaid || {})[me.id] === 'ok' ? 'text-emerald-400 bg-emerald-500/10 border-emerald-500/30' : 'text-rose-400 bg-rose-500/10 border-rose-500/30'}`}>
              {(ev.latePaid || {})[me.id] === 'ok' ? `⏱ Llegaste tarde: tu multa de S/ ${lateFeeOf(ev)} ya está en el fondo ✅` : `⏱ Llegaste tarde: multa de S/ ${lateFeeOf(ev)} para el fondo del grupo. Págala a un admin.`}
            </p>
          )}

          {isAdmin && g.length > 0 && (
            <div className="rounded-xl border border-slate-800 bg-slate-950/60 p-2.5 space-y-1.5">
              <div className="flex items-center justify-between gap-2">
                <p className="text-[11px] font-bold text-amber-400">📋 Marcar asistencia · multa por tardanza S/ {lateFeeOf(ev)} al fondo (solo admins)</p>
                <button onClick={() => allAtt(ev, g.slice(0, ev.cap || 12))} className="px-2 py-1 rounded-lg bg-emerald-600/20 border border-emerald-500/40 text-emerald-300 text-[10px] font-bold whitespace-nowrap">✅ Todos asistieron</button>
              </div>
              <div className="space-y-1">
                {g.slice(0, ev.cap || 12).map((id) => {
                  const p = byId(id); if (!p && !isGuest(id)) return null;
                  const nm = p ? p.nickname : guestName(id) + ' (inv.)';
                  const late = !!(ev.late || {})[id], lp = (ev.latePaid || {})[id] === 'ok', att = !!(ev.att || {})[id];
                  return (
                    <div key={id} className="flex items-center justify-between text-xs bg-slate-900 rounded-lg px-2 py-1.5">
                      <span>{att ? '✅ ' : ''}{nm}{late ? <b className={lp ? ' text-emerald-400' : ' text-rose-400'}>{lp ? ' · multa cobrada ✅' : ` · debe S/ ${lateFeeOf(ev)}`}</b> : ''}</span>
                      <span className="flex gap-1">
                        <button onClick={() => toggleAtt(ev, id)} className={`px-2 py-0.5 rounded-lg font-bold ${att ? 'bg-emerald-600 text-white' : 'bg-slate-700 text-slate-300'}`}>{att ? 'Asistió' : 'Faltó'}</button>
                        {late && <button onClick={() => setLatePaid(ev, id, !lp)} className="px-2 py-0.5 rounded-lg bg-emerald-600 font-bold">{lp ? '↺' : 'Cobrada'}</button>}
                        <button onClick={() => toggleLate(ev, id)} className={`px-2 py-0.5 rounded-lg font-bold ${late ? 'bg-slate-700 text-slate-300' : 'bg-rose-600/80 text-white'}`}>{late ? 'Quitar' : 'Llegó tarde'}</button>
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {!past && !(payClosed(ev) && !inRaw) && (
            <button onClick={() => toggle(ev)} className={inRaw ? 'w-full py-2.5 rounded-xl text-sm font-bold bg-slate-800 hover:bg-slate-700 text-slate-300 transition' : 'btn-fire fire-on w-full py-2.5 rounded-xl text-sm shadow transition'}>
              {inRaw ? 'No voy (salir de la lista)' : full ? 'Entrar a lista de espera' : '¡Me anoto! 🔥'}
            </button>
          )}

          {!past && isAdmin && (
            <div className="p-2.5 rounded-xl bg-slate-900/80 border border-amber-500/30">
              <label className="block text-[11px] font-bold text-amber-400 mb-1.5">➕ Anotar jugador sin cuenta (invitado)</label>
              <div className="flex gap-2 flex-wrap">
                <input id={'guest-' + ev.id} type="text" maxLength={30} placeholder="Nombre o apodo..." className={inp + ' !py-1.5 text-xs flex-1 min-w-[120px]'}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); document.getElementById('guestbtn-' + ev.id)?.click(); } }} />
                <select id={'guestpos-' + ev.id} defaultValue="" className={inp + ' !py-1.5 text-xs !w-auto'}>
                  <option value="">Posición...</option>
                  {POS.map((pos) => <option key={pos.id} value={pos.id}>{pos.label}</option>)}
                </select>
                <button id={'guestbtn-' + ev.id} type="button" onClick={async () => {
                  const el = document.getElementById('guest-' + ev.id), sp = document.getElementById('guestpos-' + ev.id);
                  if (el && el.value && await addGuest(ev, el.value, sp && sp.value)) { el.value = ''; if (sp) sp.value = ''; }
                }} className="px-3 py-1.5 bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold text-xs rounded-lg transition">Anotar</button>
              </div>
            </div>
          )}

          {mapsOf(ev) && (
            <a href={mapsOf(ev)} target="_blank" rel="noreferrer" className="block text-center w-full py-2 rounded-xl border border-blue-500/40 bg-blue-500/10 text-blue-400 text-xs font-bold hover:bg-blue-500/20 transition">📍 Abrir en Google Maps</a>
          )}

          {!past && isAdmin && g.length >= 2 && (
            <button onClick={() => onTeams(ev.id)} className="w-full py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-amber-400 text-xs font-bold transition">⚖️ Armar equipos con los {Math.min(g.length, ev.cap)} convocados</button>
          )}

          {!past && (
            <div className="grid grid-cols-2 gap-2">
              <button onClick={() => waShare(evText(ev))} className="py-2 rounded-xl border border-emerald-500/50 bg-emerald-500/10 text-emerald-300 text-xs font-bold hover:bg-emerald-500/20 transition">
                Enviar al WhatsApp 💬
              </button>
              <button onClick={() => copy('l' + ev.id, evLink(ev.id))} className="py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-bold transition">
                {cp === 'l' + ev.id ? '¡Link copiado! ✅' : '🔗 Copiar link'}
              </button>
            </div>
          )}

          {!past && isAdmin && (
            <div className="rounded-xl border border-slate-800 bg-slate-950/60 p-2.5 space-y-1.5">
              <p className="text-[11px] font-bold text-amber-400">📢 Avisos al grupo (solo admins)</p>
              <button onClick={() => editFee(ev)} className="w-full py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-amber-400 text-xs font-bold transition">💰 Cambiar cuota (ahora: {ev.fee > 0 ? 'S/ ' + ev.fee : 'gratis'})</button>
              <div className="grid gap-1.5">
                <button onClick={() => waShare(evOpen(ev))} className="py-2 rounded-xl bg-emerald-600/15 border border-emerald-500/40 text-emerald-300 text-xs font-bold hover:bg-emerald-600/25 transition">🔥 Ya está abierta la lista, anótense</button>
                <button onClick={() => { const note = prompt('Nota extra para el grupo (opcional). Déjalo vacío si no hay:', ''); if (note === null) return; waShare(evToday(ev, note.trim().slice(0, 200))); }} className="py-2 rounded-xl bg-rose-500/15 border border-rose-500/40 text-rose-300 text-xs font-bold hover:bg-rose-500/25 transition">🏐 Así será el juego de hoy</button>
                <button onClick={() => waShare(evList(ev))} className="py-2 rounded-xl bg-orange-500/15 border border-orange-500/40 text-orange-300 text-xs font-bold hover:bg-orange-500/25 transition">📋 Enviar la lista (1 a {ev.cap})</button>
                <button onClick={() => waShare(evSpots(ev))} className="py-2 rounded-xl bg-amber-500/15 border border-amber-500/40 text-amber-300 text-xs font-bold hover:bg-amber-500/25 transition">⚠️ Cupos limitados ({Math.max(0, ev.cap - g.length)} libres)</button>
                {ev.fee > 0 && (
                  <button onClick={() => waShare(evPay(ev))} className="py-2 rounded-xl bg-purple-500/15 border border-purple-500/40 text-purple-300 text-xs font-bold hover:bg-purple-500/25 transition">💸 Falta pagar ({g.slice(0, ev.cap).filter((id) => pays[id] !== 'ok').length})</button>
                )}
              </div>
              <p className="text-[10px] text-slate-500">Se abre WhatsApp con el mensaje listo; solo elige el grupo y envía.</p>
            </div>
          )}

          {ev.fee > 0 && (
            <div className="border-t border-slate-800 pt-3 space-y-2">
              <div className="flex justify-between text-sm">
                <b>💰 Cuota: S/ {ev.fee}</b>
                {!past && <span className={`text-[11px] font-bold ${payClosed(ev) ? 'text-rose-400' : 'text-amber-400'}`}>{payClosed(ev) ? '⛔ Plazo de pago vencido' : `⏰ Paga antes del ${fmtDL(ev)}`}</span>}
              </div>
              {!past && payClosed(ev) && inRaw && !iGo && (
                <p className="text-xs text-rose-400 bg-rose-500/10 border border-rose-500/30 rounded-xl p-2 font-bold text-center">Perdiste tu cupo por no pagar a tiempo. Si ya pagaste, avisa abajo y un admin lo confirma.</p>
              )}

              <div className="flex items-center justify-between gap-2 bg-purple-500/10 border border-purple-500/30 rounded-xl p-2.5">
                <div>
                  <p className="text-[10px] text-slate-400">Yape a nombre de {YAPE_NAME}</p>
                  <b className="num text-2xl text-purple-400">{YAPE_NUM}</b>
                </div>
                <button onClick={() => copy('y' + ev.id, YAPE_NUM.replace(/\s/g, ''))} className="px-3 py-1.5 rounded-xl bg-purple-500/20 border border-purple-500/40 text-purple-300 text-xs font-bold">
                  {cp === 'y' + ev.id ? '¡Copiado! ✅' : 'Copiar número'}
                </button>
              </div>

              {(iGo || inRaw) && (
                mine === 'ok' ? (
                  <p className="text-xs text-emerald-400 bg-emerald-500/10 border border-emerald-500/30 rounded-xl p-2 font-bold text-center">✅ Tu pago de cancha está confirmado</p>
                ) : mine === 'pending' ? (
                  <div className="space-y-1.5">
                    <p className="text-xs text-amber-400 bg-amber-500/10 border border-amber-500/30 rounded-xl p-2 font-bold text-center">⏳ Pago avisado. Un admin lo confirmará con el ✓.</p>
                    <button onClick={() => payYape(ev)} className="w-full py-1.5 rounded-xl bg-slate-800 text-slate-300 text-[11px] font-bold">Reenviar aviso a {YAPE_NAME} por WhatsApp 💬</button>
                  </div>
                ) : (
                  <button onClick={() => payYape(ev)} className="w-full py-2 rounded-xl border border-purple-500/60 bg-purple-500/10 text-purple-300 text-xs font-bold hover:bg-purple-500/20 transition">
                    Ya yapeé · avisar a {YAPE_NAME} por WhatsApp 💬
                  </button>
                )
              )}

              {isAdmin && payClosed(ev) && raw.length > g.length && (
                <button onClick={() => confirm(`¿Quitar de la lista a los ${raw.length - g.length} que no pagaron?`) && db.collection('events').doc(ev.id).update({ going: FV.arrayRemove(...raw.filter((id) => !g.includes(id))) })} className="w-full py-2 rounded-xl border border-rose-500/50 bg-rose-500/10 text-rose-300 text-xs font-bold">
                  Quitar de la lista a los {raw.length - g.length} que no pagaron ✂️
                </button>
              )}
              {isAdmin && (
                <p className="text-xs text-slate-400">
                  Recaudado: <b className="text-emerald-400">S/ {ok * ev.fee}</b> de S/ {g.length * ev.fee}
                </p>
              )}

              {canManage && g.length > 0 && (
                <div className="space-y-1.5 pt-1">
                  <p className="text-[11px] font-bold text-amber-400">Control de cobros (solo admins pueden poner el ✓):</p>
                  {g.map((id) => {
                    const p = byId(id), st = pays[id];
                    if (!p && !isGuest(id)) return null;
                    return (
                      <div key={id} className="flex items-center justify-between text-xs bg-slate-950 rounded-xl px-2.5 py-1.5 border border-slate-800">
                        <span>{p ? `${p.avatar} ${p.nickname}` : `🎟️ ${guestName(id)} (inv.)`}</span>
                        <div className="flex items-center gap-2">
                          <span className={st === 'ok' ? 'text-emerald-400 font-bold' : st === 'pending' ? 'text-amber-400 font-bold' : 'text-slate-500'}>
                            {st === 'ok' ? 'Pagado' : st === 'pending' ? 'Avisó pago' : 'Debe'}
                          </span>
                          {st !== 'ok' ? (
                            <button onClick={() => setPaid(ev, id, 'ok')} title="Aprobar pago" className="px-2 py-0.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white font-bold">✓</button>
                          ) : (
                            <button onClick={() => setPaid(ev, id, null)} title="Revertir pago" className="px-2 py-0.5 rounded-lg bg-slate-800 text-slate-400 hover:text-white">↺</button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </div>
      </article>
    );
  };

  const all = events.filter((e) => e.date).sort((a, b) => when(a) - when(b));
  const limit = Date.now() - 6 * 36e5;
  const up = all.filter((e) => when(e) >= limit);
  const past = all.filter((e) => when(e) < limit);
  const fund = fundOf(events, me.id);

  return (
    <div className="space-y-4">
      {isAdmin && (
        <button onClick={() => setOpen(!open)} className="btn-fire w-full py-2.5 rounded-xl text-sm shadow">
          {open ? 'Cerrar formulario' : '+ Nueva convocatoria de pichanga'}
        </button>
      )}

      <div className={card + ' space-y-1'}>
        <div className="flex items-center justify-between"><b className="text-sm">🏦 Fondo del grupo</b><span className="num text-xl text-emerald-400 font-black">S/ {fund.paid}</span></div>
        <p className="text-[11px] text-slate-400">Llegar tarde = multa de S/ {LATE_FEE} que va al fondo.{fund.due > 0 ? ` Por cobrar: S/ ${fund.due}.` : ''}</p>
        {fund.mine > 0 && <p className="text-xs text-rose-400 font-bold">Tienes S/ {fund.mine} de multas por pagar.</p>}
      </div>

      {created && (
        <div className={card + ' border-emerald-500/40 space-y-2.5 enter'}>
          <p className="text-sm font-bold text-emerald-400">✅ ¡Pichanga publicada! Ahora avisa al grupo</p>
          <p className="text-[11px] text-slate-400">Al tocar el link, la gente entra directo a esta pichanga para anotarse.</p>
          <div className="flex flex-wrap gap-2">
            <button onClick={() => waShare(evOpen(created))} className="flex-1 min-w-[160px] py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold transition">Avisar al grupo: lista abierta 💬</button>
            <button onClick={() => copy('new', evLink(created.id))} className="flex-1 min-w-[140px] py-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-bold transition">{cp === 'new' ? '¡Copiado! ✅' : '🔗 Copiar link'}</button>
            <button onClick={() => setCreated(null)} className="px-3 py-2.5 rounded-xl bg-slate-800 text-slate-400 text-xs font-bold">Cerrar</button>
          </div>
        </div>
      )}

      {open && (
        <form onSubmit={create} className={card + ' space-y-2.5 enter'}>
          <p className="text-sm font-bold text-amber-400">Crear convocatoria</p>
          <input required className={inp} placeholder="Título (ej. Pichanga Sábado por la tarde)" value={f.title} onChange={(e) => setF({ ...f, title: e.target.value })} />
          <div className="grid grid-cols-2 gap-2">
            <input required type="date" className={inp} value={f.date} onChange={(e) => setF({ ...f, date: e.target.value })} />
            <input type="time" className={inp} value={f.time} onChange={(e) => setF({ ...f, time: e.target.value })} />
          </div>
          <input className={inp} placeholder="Lugar (ej. Cancha Papú, Coliseo Berlín...)" value={f.place} onChange={(e) => setF({ ...f, place: e.target.value })} />
          <input className={inp} placeholder="🗺 Link de Google Maps (pega el link de la cancha)" value={f.maps} onChange={(e) => setF({ ...f, maps: e.target.value })} />
          <div className="grid grid-cols-2 gap-2">
            <input type="number" min="0" step="0.5" className={inp} placeholder="Cuota por persona (S/)" value={f.fee} onChange={(e) => setF({ ...f, fee: e.target.value })} />
            <input type="number" min="2" className={inp} placeholder="Cupos (ej. 12)" value={f.cap} onChange={(e) => setF({ ...f, cap: e.target.value })} />
          </div>
          <p className="text-[11px] text-slate-400">💜 El Yape de cobro es siempre el de {YAPE_NAME}: {YAPE_NUM}</p>
          <button className="btn-fire w-full py-2.5 rounded-xl text-sm font-black shadow mt-1">Publicar Convocatoria</button>
        </form>
      )}

      {up.length === 0 && !open && (
        <p className="text-center text-sm text-slate-500 py-10">No hay pichangas convocadas por el momento. ¡Atentos al muro!</p>
      )}

      {up.map((e) => renderEv(e, false))}

      {past.length > 0 && (
        <div className="pt-2">
          <p className="text-xs font-bold text-slate-500 mb-2">Partidos anteriores</p>
          {past.filter((e, i) => i >= past.length - 3 || e.id === focusId).reverse().map((e) => renderEv(e, true))}
        </div>
      )}
    </div>
  );
}

// ===== PANEL DE ADMINISTRADORES (EXCLUSIVO JUSTIN & YULISA) =====
// ===== Editor de score (habilidades) de un jugador — solo admins =====
function SkillEditor({ player, onClose, onSave }) {
  const [p, setP] = useState(() => { const c = JSON.parse(JSON.stringify(player)); c.skills = Object.fromEntries(SK.map((k) => [k, skv(c.skills, k)])); return c; });
  const [busy, setBusy] = useState(false);
  const sk = (k) => (p.skills && p.skills[k]) || 3;
  const shift = (d) => setP({ ...p, skills: Object.fromEntries(SK.map((k) => [k, Math.min(5, Math.max(1, sk(k) + d))])) });
  const posOk = POS.some((x) => x.id === p.position);
  const save = async () => {
    setBusy(true);
    try {
      const skills = Object.fromEntries(SK.map((k) => [k, sk(k)]));
      if (onSave) await onSave(skills, posOk ? p.position : '');
      else await db.collection('players').doc(p.id).update({ skills, position: p.position });
      onClose();
    } catch (e) { alert('No se pudo guardar: ' + e.message); }
    setBusy(false);
  };
  return (
    <div className="fixed inset-0 z-50 bg-black/85 flex items-center justify-center p-3">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-sm p-5 space-y-3 text-xs enter shadow-2xl max-h-[92vh] overflow-y-auto">
        <div className="flex justify-between items-center border-b border-slate-800 pb-2">
          <b className="text-sm text-amber-400">Score de {p.nickname}</b>
          <button onClick={onClose} className="text-slate-400 hover:text-white text-base">✕</button>
        </div>
        <div className="flex items-center justify-between bg-slate-950 border border-slate-800 rounded-xl p-2.5">
          <span className="text-slate-400">⭐ Score general</span>
          <b className="text-2xl font-mono text-amber-400">{ovr(p.skills).toFixed(1)}</b>
          <span className="flex gap-1.5">
            <button onClick={() => shift(-1)} className="px-2.5 py-1.5 rounded-lg bg-slate-800 text-rose-300 font-bold">−1 todo</button>
            <button onClick={() => shift(1)} className="px-2.5 py-1.5 rounded-lg bg-slate-800 text-emerald-300 font-bold">+1 todo</button>
          </span>
        </div>
        <div>
          <label className="block text-[11px] text-slate-400 mb-1">Posición</label>
          <select className={inp} value={posOk ? p.position : ''} onChange={(e) => setP({ ...p, position: e.target.value })}>
            {!posOk && <option value="">¿Pos?</option>}
            {POS.map((pos) => <option key={pos.id} value={pos.id}>{pos.label}</option>)}
          </select>
        </div>
        <div className="space-y-2 pt-1">
          {SK.map((k) => (
            <div key={k} className="flex justify-between items-center gap-2 bg-slate-950 p-2 rounded-xl border border-slate-800">
              <span className="capitalize w-24 text-slate-400">{skLabel(k)}</span>
              <input type="range" min="1" max="5" value={sk(k)} className="flex-1 accent-orange-500 cursor-pointer" onChange={(e) => setP({ ...p, skills: { ...p.skills, [k]: +e.target.value } })} />
              <b className="w-5 text-right text-amber-400 font-mono">{sk(k)}</b>
            </div>
          ))}
        </div>
        <div className="flex gap-2 pt-2">
          <button onClick={onClose} className="w-1/2 py-2 bg-slate-800 hover:bg-slate-700 rounded-xl font-bold transition">Cancelar</button>
          <button disabled={busy} onClick={save} className="btn-fire w-1/2 py-2 rounded-xl font-black shadow transition disabled:opacity-50">{busy ? 'Guardando...' : 'Guardar'}</button>
        </div>
      </div>
    </div>
  );
}

