// ===== REGISTRO DE PARTIDOS (MODAL DE RESULTADO) =====
function MatchModal({ players, init, onClose }) {
  const [side, setSide] = useState(() => {
    const s = {};
    (init.a || []).forEach((i) => (s[i] = 'A'));
    (init.b || []).forEach((i) => (s[i] = 'B'));
    return s;
  });
  const [sa, setSa] = useState(2);
  const [sb, setSb] = useState(0);
  const [mvp, setMvp] = useState('');

  const cyc = (id) => {
    const c = side[id];
    const nx = { ...side };
    if (!c) nx[id] = 'A';
    else if (c === 'A') nx[id] = 'B';
    else delete nx[id];
    setSide(nx);
  };

  const guestRows = [...(init.a || []), ...(init.b || [])].filter(isGuest).map((id) => ({ id, nickname: guestName(id) + ' (inv.)', avatar: '🎟️' }));
  const rows = [...players, ...guestRows];
  const A = Object.keys(side).filter((i) => side[i] === 'A');
  const B = Object.keys(side).filter((i) => side[i] === 'B');

  const submit = async (e) => {
    e.preventDefault();
    if (!A.length || !B.length) return alert('Debes marcar al menos un jugador en cada equipo.');
    if (sa === sb) return alert('Los sets no pueden quedar empatados.');

    const winA = sa > sb, W = winA ? A : B, L = winA ? B : A, ws = winA ? sa : sb;
    const batch = db.batch();

    W.filter((id) => !isGuest(id)).forEach((id) => batch.update(db.collection('players').doc(id), {
      matchesWon: FV.increment(1),
      setsWon: FV.increment(ws)
    }));
    L.filter((id) => !isGuest(id)).forEach((id) => batch.update(db.collection('players').doc(id), {
      matchesLost: FV.increment(1)
    }));
    if (mvp) {
      batch.update(db.collection('players').doc(mvp), { mvpCount: FV.increment(1) });
    }

    batch.set(db.collection('matches').doc(), {
      teamA: A,
      teamB: B,
      scoreA: sa,
      scoreB: sb,
      mvp,
      createdAt: Date.now()
    });

    const names = (ids) => ids.map((i) => players.find((p) => p.id === i)?.nickname || (isGuest(i) ? guestName(i) + ' (inv.)' : 'Jugador')).join(', ');
    const m = players.find((p) => p.id === mvp);

    batch.set(db.collection('posts').doc(), {
      authorId: 'bot',
      authorName: 'IceFire Árbitro',
      nick: 'arbitro',
      avatar: '🏆',
      content: `🏆 ¡RESULTADO OFICIAL REGISTRADO!\n\n🔥 Marcador: Equipo A (${sa}) - (${sb}) Equipo B\n\n🔵 Equipo A: ${names(A)}\n🔴 Equipo B: ${names(B)}${m ? `\n\n⭐ JUGADOR MVP: ${m.nickname} ${m.avatar}` : ''}`,
      badge: '🔥 Resultado',
      likes: [],
      comments: [],
      createdAt: Date.now()
    });

    await batch.commit();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-3">
      <form onSubmit={submit} className="bg-slate-900 border border-slate-800 rounded-3xl w-full max-w-md max-h-[92vh] overflow-y-auto p-5 space-y-3 text-sm enter shadow-2xl">
        <div className="flex justify-between items-center border-b border-slate-800 pb-2">
          <b className="text-base text-amber-400">Registrar Partido Oficial</b>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-white">✕</button>
        </div>

        <p className="text-xs text-slate-400 leading-relaxed">
          Toca a los jugadores para armar los bandos: <span className="text-blue-400 font-bold">1 toque = Equipo A</span>, <span className="text-rose-400 font-bold">2 toques = Equipo B</span>, 3 = Fuera.
        </p>

        <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto p-1">
          {rows.map((p) => {
            const sideCode = side[p.id];
            return (
              <button type="button" key={p.id} onClick={() => cyc(p.id)} className={`p-2 rounded-xl border text-left flex justify-between items-center transition ${sideCode === 'A' ? 'bg-blue-600/25 border-blue-500 text-blue-200' : sideCode === 'B' ? 'bg-rose-600/25 border-rose-500 text-rose-200' : 'bg-slate-950 border-slate-800 text-slate-500'}`}>
                <span className="truncate">{p.avatar} {p.nickname}</span>
                <b className="font-bold">{sideCode || '-'}</b>
              </button>
            );
          })}
        </div>

        <div className="grid grid-cols-2 gap-3 bg-slate-950 p-3 rounded-2xl border border-slate-800">
          <label className="text-xs text-slate-400">Sets Equipo A
            <input type="number" min="0" max="5" className={inp + ' mt-1 font-bold text-center'} value={sa} onChange={(e) => setSa(+e.target.value || 0)} />
          </label>
          <label className="text-xs text-slate-400">Sets Equipo B
            <input type="number" min="0" max="5" className={inp + ' mt-1 font-bold text-center'} value={sb} onChange={(e) => setSb(+e.target.value || 0)} />
          </label>
        </div>

        <div>
          <label className="block text-xs text-slate-400 mb-1">Elegir MVP del partido</label>
          <select className={inp} value={mvp} onChange={(e) => setMvp(e.target.value)}>
            <option value="">⭐ Selecciona el mejor jugador (opcional)</option>
            {players.map((p) => <option key={p.id} value={p.id}>{p.avatar} {p.nickname}</option>)}
          </select>
        </div>

        <div className="flex gap-2 pt-2">
          <button type="button" onClick={onClose} className="w-1/2 py-2.5 bg-slate-800 hover:bg-slate-700 rounded-xl font-bold transition">Cancelar</button>
          <button className="btn-fire w-1/2 py-2.5 rounded-xl font-black shadow transition">Guardar en Ranking</button>
        </div>
      </form>
    </div>
  );
}

// ===== PERFIL (PÁGINA COMPLETA, CON ENLACE PROPIO) =====
const hashId = () => { const m = location.hash.match(/^#\/p\/(.+)$/); return m ? decodeURIComponent(m[1]) : null; };

function ProfileHistory({ id, players }) {
  const [ms, setMs] = useState(null);
  useEffect(() => {
    let off = false;
    setMs(null);
    Promise.all([
      db.collection('matches').where('teamA', 'array-contains', id).limit(100).get(),
      db.collection('matches').where('teamB', 'array-contains', id).limit(100).get()
    ]).then(([a, b]) => {
      if (off) return;
      const seen = {};
      [...a.docs, ...b.docs].forEach((d) => { seen[d.id] = { id: d.id, ...d.data() }; });
      setMs(Object.values(seen).sort((x, y) => (y.createdAt || 0) - (x.createdAt || 0)));
    }).catch(() => { if (!off) setMs([]); });
    return () => { off = true; };
  }, [id]);

  if (ms === null) return <div className={card + ' text-center text-xs text-slate-500'}>Cargando historial…</div>;
  if (!ms.length) return <div className={card + ' text-center text-xs text-slate-500'}>Aún no tiene partidos registrados.</div>;

  const rows = ms.map((m) => {
    const inA = (m.teamA || []).includes(id);
    const my = inA ? m.scoreA : m.scoreB, rival = inA ? m.scoreB : m.scoreA;
    return { m, my, rival, won: my > rival, draw: my === rival };
  });
  let cur = 0; for (const r of rows) { if (r.won) cur++; else break; }
  let best = 0, run = 0;
  [...rows].reverse().forEach((r) => { run = r.won ? run + 1 : 0; best = Math.max(best, run); });
  const mvps = rows.filter((r) => r.m.mvp === id).length;
  const nameOf = (i) => (players.find((p) => p.id === i) || {}).nickname || 'Jugador';

  return (
    <div className={card + ' space-y-2'}>
      <p className="text-xs font-bold text-amber-400">Historial de partidos</p>
      <div className="grid grid-cols-3 gap-2 text-center">
        {[['Racha actual', cur ? '🔥' + cur : '0'], ['Mejor racha', best], ['Partidos', rows.length + (rows.length >= 100 ? '+' : '')]].map(([l, v]) => (
          <div key={l} className="af-stat">
            <div className="num text-xl text-amber-400">{v}</div>
            <div className="text-[10px] text-slate-500 mt-1">{l}</div>
          </div>
        ))}
      </div>
      {mvps > 0 && <p className="text-[11px] text-slate-400">⭐ MVP en {mvps} de sus últimos {rows.length} partidos</p>}
      <div className="space-y-1.5">
        {rows.slice(0, 10).map(({ m, my, rival, won, draw }) => (
          <div key={m.id} className="flex items-center gap-2 bg-slate-950 border border-slate-800/80 rounded-xl px-2.5 py-1.5 text-xs">
            <span className={'font-black w-5 ' + (won ? 'text-emerald-400' : draw ? 'text-slate-400' : 'text-rose-400')}>{won ? 'G' : draw ? 'E' : 'P'}</span>
            <b className="num text-base text-slate-100">{my}–{rival}</b>
            <span className="flex-1 min-w-0 truncate text-slate-500">{m.mvp ? '⭐ ' + nameOf(m.mvp) : ''}</span>
            {m.createdAt && <span className="text-[10px] text-slate-500 shrink-0">{ago(m.createdAt)}</span>}
          </div>
        ))}
      </div>
    </div>
  );
}

// ===== Asistencias: calendario por jugador =====
function AttendanceCard({ id, events, isAdmin }) {
  const [m, setM] = useState(() => { const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), 1); });
  const [sel, setSel] = useState(null);
  const [busy, setBusy] = useState(false);
  const [shown, setShown] = useState(0);
  const evs = events.filter((e) => e.date).sort((a, b) => when(a) - when(b));

  // Estado de cada pichanga para este jugador
  const status = (e) => {
    const a = (e.att || {})[id], isIn = (e.going || []).includes(id);
    const over = when(e).getTime() + 3 * 36e5 < Date.now(), taken = Object.keys(e.att || {}).length > 0;
    if (a === true) return 'ok';
    if (a === false) return 'miss';
    if (isIn && over) return taken ? 'miss' : 'pend';
    if (isIn) return 'soon';
    return 'other';
  };
  const isLate = (e) => !!(e.late || {})[id];

  const ok = evs.filter((e) => status(e) === 'ok').length, miss = evs.filter((e) => status(e) === 'miss').length;
  const lates = evs.filter(isLate).length;
  const pct = ok + miss ? Math.round((ok / (ok + miss)) * 100) : null;

  // Racha: pichangas seguidas con asistencia (cuenta solo las ya decididas)
  const decided = evs.filter((e) => status(e) === 'ok' || status(e) === 'miss').map((e) => status(e));
  let streak = 0, best = 0, run = 0;
  decided.forEach((st) => { if (st === 'ok') { run++; best = Math.max(best, run); } else run = 0; });
  for (let i = decided.length - 1; i >= 0 && decided[i] === 'ok'; i--) streak++;

  // Anillo animado
  useEffect(() => { const t = setTimeout(() => setShown(pct || 0), 120); return () => clearTimeout(t); }, [pct]);
  const R = 26, C = 2 * Math.PI * R;
  const ringColor = pct === null ? '#475569' : pct >= 80 ? '#34d399' : pct >= 50 ? '#fbbf24' : '#fb7185';

  // Forma reciente: últimas 8 pichangas donde estuvo anotado
  const recent = evs.filter((e) => status(e) !== 'other').slice(-8);

  const byDay = {};
  evs.forEach((e) => { const st = status(e); const prev = byDay[e.date]; const rank = { ok: 4, miss: 3, soon: 2, pend: 1, other: 0 }; if (!prev || rank[st] > rank[prev]) byDay[e.date] = st; });
  const y = m.getFullYear(), mo = m.getMonth();
  const offset = (new Date(y, mo, 1).getDay() + 6) % 7, days = new Date(y, mo + 1, 0).getDate();
  const cls = { ok: 'bg-emerald-500/25 border border-emerald-500/50 text-emerald-300 font-black', miss: 'bg-rose-500/20 border border-rose-500/40 text-rose-300 font-black', soon: 'bg-amber-500/20 border border-amber-500/40 text-amber-300 font-black', pend: 'bg-slate-700/60 border border-slate-600 text-slate-200 font-bold', other: 'bg-slate-800/70 border border-slate-700 text-slate-300' };
  const key = (d) => `${y}-${String(mo + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  const now = new Date(), todayKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

  // Marcar (solo admins)
  const upd = async (e, patch) => {
    setBusy(true);
    try { await db.collection('events').doc(e.id).update(patch); }
    catch (x) { console.error(x); alert('No se pudo guardar la asistencia.'); }
    setBusy(false);
  };
  const clearLate = { ['late.' + id]: FV.delete(), ['latePaid.' + id]: FV.delete() };
  const markOk = (e) => upd(e, { ['att.' + id]: true });
  const markMiss = (e) => upd(e, { ['att.' + id]: false, ...clearLate });
  const markLate = (e) => upd(e, isLate(e) ? clearLate : { ['late.' + id]: true, ['att.' + id]: true });
  const markClear = (e) => upd(e, { ['att.' + id]: FV.delete(), ...clearLate });

  const label = { ok: '✅ Asistió', miss: '❌ Faltó', soon: '🕒 Anotado, aún no juega', pend: '⏳ Falta pasar lista', other: 'No estaba anotado' };
  const dayEvs = sel ? evs.filter((e) => e.date === sel) : [];
  const medal = pct === 100 && ok >= 3 ? '🏆 Asistencia perfecta' : streak >= 3 ? `🔥 Racha de ${streak}` : null;

  return (
    <div className={card + ' space-y-3'}>
      <div className="flex items-center justify-between">
        <b className="text-sm">📅 Asistencias</b>
        <div className="flex items-center gap-2">
          <button onClick={() => setM(new Date(y, mo - 1, 1))} className="w-7 h-7 rounded-lg bg-slate-800 text-slate-300">‹</button>
          <button onClick={() => setM(new Date(now.getFullYear(), now.getMonth(), 1))} className="text-xs font-bold capitalize w-28 text-center">{m.toLocaleDateString('es-PE', { month: 'long', year: 'numeric' })}</button>
          <button onClick={() => setM(new Date(y, mo + 1, 1))} className="w-7 h-7 rounded-lg bg-slate-800 text-slate-300">›</button>
        </div>
      </div>

      <div className="flex items-center gap-3">
        <div className="relative w-16 h-16 shrink-0">
          <svg viewBox="0 0 64 64" className="w-16 h-16 -rotate-90">
            <circle cx="32" cy="32" r={R} fill="none" stroke="#1e293b" strokeWidth="7" />
            <circle cx="32" cy="32" r={R} fill="none" stroke={ringColor} strokeWidth="7" strokeLinecap="round" strokeDasharray={C} strokeDashoffset={C * (1 - shown / 100)} style={{ transition: 'stroke-dashoffset .9s ease, stroke .4s' }} />
          </svg>
          <span className="absolute inset-0 flex items-center justify-center num text-sm font-black" style={{ color: ringColor }}>{pct === null ? '–' : pct + '%'}</span>
        </div>
        <div className="flex-1 grid grid-cols-4 gap-1.5 text-center">
          <div className="rounded-xl bg-slate-950/60 p-1.5"><b className="num text-base text-emerald-400">{ok}</b><p className="text-[9px] text-slate-400">Asistió</p></div>
          <div className="rounded-xl bg-slate-950/60 p-1.5"><b className="num text-base text-rose-400">{miss}</b><p className="text-[9px] text-slate-400">Faltó</p></div>
          <div className="rounded-xl bg-slate-950/60 p-1.5"><b className="num text-base text-amber-400">{streak}🔥</b><p className="text-[9px] text-slate-400">Racha{best > streak ? ` (mejor ${best})` : ''}</p></div>
          <div className="rounded-xl bg-slate-950/60 p-1.5"><b className="num text-base text-orange-400">{lates}</b><p className="text-[9px] text-slate-400">Tarde</p></div>
        </div>
      </div>

      {medal && <p className="text-xs font-bold text-center rounded-xl py-1.5 bg-amber-500/10 border border-amber-500/30 text-amber-300">{medal}</p>}

      {recent.length > 0 && (
        <div className="flex items-center gap-1.5">
          <span className="text-[10px] text-slate-400">Últimas:</span>
          {recent.map((e) => { const st = status(e); return <span key={e.id} title={`${e.title} · ${e.date}`} className={`w-6 h-6 rounded-full flex items-center justify-center text-[11px] ${st === 'ok' ? (isLate(e) ? 'bg-orange-500/25 border border-orange-500/50' : 'bg-emerald-500/25 border border-emerald-500/50') : st === 'miss' ? 'bg-rose-500/25 border border-rose-500/50' : 'bg-slate-700/60 border border-slate-600'}`}>{st === 'ok' ? (isLate(e) ? '⏱' : '✓') : st === 'miss' ? '✕' : '·'}</span>; })}
        </div>
      )}

      <div className="grid grid-cols-7 gap-1 text-center text-[10px] text-slate-500 font-bold">{['L', 'M', 'M', 'J', 'V', 'S', 'D'].map((d, i) => <span key={i}>{d}</span>)}</div>
      <div className="grid grid-cols-7 gap-1">
        {Array.from({ length: offset }).map((_, i) => <span key={'o' + i} />)}
        {Array.from({ length: days }).map((_, i) => {
          const k = key(i + 1), st = byDay[k], has = evs.some((e) => e.date === k);
          return (
            <button key={i} disabled={!has} onClick={() => setSel(sel === k ? null : k)}
              className={`h-9 rounded-lg flex items-center justify-center text-xs transition ${st ? cls[st] : 'text-slate-600'} ${sel === k ? 'ring-2 ring-orange-500 scale-105' : ''} ${k === todayKey && sel !== k ? 'outline outline-1 outline-slate-500' : ''} ${has ? 'cursor-pointer active:scale-95' : 'cursor-default'}`}>{i + 1}</button>
          );
        })}
      </div>

      {!sel && <p className="text-[10px] text-slate-500 text-center">{isAdmin ? 'Toca un día con pichanga para ver el detalle y marcar la asistencia.' : 'Toca un día con pichanga para ver el detalle.'}</p>}

      {dayEvs.map((e) => {
        const st = status(e), isIn = (e.going || []).includes(id), canMark = isAdmin && (isIn || (e.att || {})[id] !== undefined);
        return (
          <div key={e.id} className="rounded-xl border border-slate-800 bg-slate-950/60 p-2.5 space-y-2 enter">
            <div className="flex items-center justify-between gap-2">
              <div className="min-w-0">
                <b className="block truncate text-xs text-slate-100">{e.title}</b>
                <p className="text-[10px] text-slate-400">🗓 {fmtDay(e)} · 🕗 {fmtHour(e)}</p>
              </div>
              <span className="text-[11px] font-bold text-right">{label[st]}{isLate(e) && <span className="block text-orange-400">⏱ Llegó tarde{(e.latePaid || {})[id] === 'ok' ? ' · multa cobrada ✅' : ` · debe S/ ${lateFeeOf(e)}`}</span>}</span>
            </div>
            {canMark && (
              <div className="flex flex-wrap gap-1.5">
                <button disabled={busy} onClick={() => markOk(e)} className={`px-2.5 py-1 rounded-lg text-[11px] font-bold disabled:opacity-50 ${st === 'ok' ? 'bg-emerald-600 text-white' : 'bg-slate-800 text-slate-300'}`}>✅ Asistió</button>
                <button disabled={busy} onClick={() => markMiss(e)} className={`px-2.5 py-1 rounded-lg text-[11px] font-bold disabled:opacity-50 ${st === 'miss' ? 'bg-rose-600 text-white' : 'bg-slate-800 text-slate-300'}`}>❌ Faltó</button>
                <button disabled={busy} onClick={() => markLate(e)} className={`px-2.5 py-1 rounded-lg text-[11px] font-bold disabled:opacity-50 ${isLate(e) ? 'bg-orange-600 text-white' : 'bg-slate-800 text-slate-300'}`}>⏱ {isLate(e) ? 'Quitar tarde' : 'Llegó tarde'}</button>
                {(e.att || {})[id] !== undefined && <button disabled={busy} onClick={() => markClear(e)} className="px-2.5 py-1 rounded-lg text-[11px] font-bold bg-slate-800 text-slate-400 disabled:opacity-50">↺ Limpiar</button>}
              </div>
            )}
            {isAdmin && !canMark && <p className="text-[10px] text-slate-500">Este jugador no estaba anotado en esta pichanga.</p>}
          </div>
        );
      })}

      <div className="flex flex-wrap gap-x-3 gap-y-1 text-[10px] text-slate-400">
        <span><b className="text-emerald-400">■</b> Asistió</span><span><b className="text-rose-400">■</b> Faltó</span><span><b className="text-amber-400">■</b> Anotado, falta jugar</span><span><b className="text-slate-300">■</b> Sin pasar lista / no anotado</span>
      </div>
    </div>
  );
}

function ProfilePage({ id, me, players, posts, isAdmin, events, onProfile, onClose, onMessage }) {
  const p = players.find((x) => x.id === id);
  const [busy, setBusy] = useState(false);
  const [ed, setEd] = useState(null);
  const [copied, setCopied] = useState(false);

  if (!p) {
    return (
      <div className={card + ' text-center space-y-3 py-10'}>
        <p className="text-sm text-slate-400">Este perfil no existe o ya no está en la comunidad.</p>
        <button onClick={onClose} className="btn-fire px-4 py-2 rounded-xl text-sm">Volver</button>
      </div>
    );
  }

  const mine = p.id === me.id;
  const t = (p.matchesWon || 0) + (p.matchesLost || 0);
  const winRate = t ? Math.round(((p.matchesWon || 0) / t) * 100) : 0;
  const list = posts.filter((x) => x.wallOwner === p.id || (x.authorId === p.id && !x.wallOwner)).sort((a, b) => b.createdAt - a.createdAt).slice(0, 50);
  const link = SITE_URL + '#/p/' + p.id;
  const since = p.createdAt ? `${MESES[new Date(p.createdAt).getMonth()]} de ${new Date(p.createdAt).getFullYear()}` : '';

  const changePhoto = async (e) => {
    const f = e.target.files && e.target.files[0];
    e.target.value = '';
    if (!f) return;
    setBusy(true);
    try {
      const photo = await fileToDataUrl(f, 320, 0.75);
      await db.collection('players').doc(p.id).update({ photo });
    } catch (x) { alert('No se pudo guardar la foto. Prueba con otra.'); }
    setBusy(false);
  };
  const removePhoto = () => db.collection('players').doc(p.id).update({ photo: FV.delete() });
  const saveEd = async (e) => {
    e.preventDefault();
    try {
      await db.collection('players').doc(p.id).update({ nickname: ed.nickname.trim() || p.nickname, avatar: ed.avatar, phone: ed.phone.trim() });
      setEd(null);
    } catch (x) { alert('No se pudieron guardar los cambios.'); }
  };
  const copyLink = () => {
    if (navigator.clipboard) navigator.clipboard.writeText(link).catch(() => {});
    setCopied(true); setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-3 enter">
      <button onClick={onClose} className="text-xs font-bold text-slate-400 hover:text-slate-200 flex items-center gap-1">← Volver</button>

      <div className={card + ' !p-0 overflow-hidden'}>
        <div className="af-cover h-28 sm:h-36" />
        <div className="px-4 pb-4">
          <div className="flex items-end justify-between -mt-12">
            <Av p={p} size="w-24 h-24" text="text-6xl" />
            <div className="flex gap-1.5 pb-1">
              {!mine && <button onClick={() => onMessage(p.id)} className="btn-fire px-4 py-2 rounded-xl text-xs">Mensaje 💬</button>}
              <button onClick={copyLink} className="px-3 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-bold transition">{copied ? '¡Copiado! ✅' : '🔗 Copiar enlace'}</button>
            </div>
          </div>

          <div className="mt-2">
            <b className="text-2xl text-slate-100 block leading-tight">{p.nickname}</b>
            <p className="text-sm text-slate-400">{p.name}</p>
            <div className="flex flex-wrap items-center gap-2 mt-1.5">
              <Badge id={p.position} />
              <span className="text-xs font-black text-amber-400">⭐ {ovr(p.skills).toFixed(1)} OVR</span>
              {p.isAdmin && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-amber-500/15 text-amber-400 border border-amber-500/30">Admin</span>}
              {since && <span className="text-[11px] text-slate-500">En IceFire desde {since}</span>}
            </div>
          </div>

          {mine && (
            <div className="flex flex-wrap gap-2 mt-3">
              <label className="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-amber-400 text-xs font-bold cursor-pointer transition">
                {busy ? 'Subiendo...' : '📷 Cambiar foto'}
                <input type="file" accept="image/*" className="hidden" onChange={changePhoto} />
              </label>
              {p.photo && <button onClick={removePhoto} className="px-3 py-1.5 rounded-xl bg-slate-800 text-slate-300 text-xs font-bold">Quitar foto</button>}
              <button onClick={() => setEd(ed ? null : { nickname: p.nickname || '', avatar: p.avatar || '🏐', phone: p.phone || '' })} className="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-amber-400 text-xs font-bold transition">✏️ Editar datos</button>
              <button onClick={() => { if (confirm('¿Deseas cerrar tu sesión?')) auth.signOut(); }} className="px-3 py-1.5 rounded-xl bg-rose-500/15 border border-rose-500/40 text-rose-300 text-xs font-bold">Cerrar sesión</button>
            </div>
          )}

          {mine && ed && (
            <form onSubmit={saveEd} className="bg-slate-950 border border-slate-800 rounded-2xl p-3 space-y-2 mt-3">
              <input className={inp} placeholder="Apodo" value={ed.nickname} onChange={(e) => setEd({ ...ed, nickname: e.target.value })} />
              <div className="grid grid-cols-2 gap-2">
                <select className={inp} value={ed.avatar} onChange={(e) => setEd({ ...ed, avatar: e.target.value })}>
                  {AV.map((a) => <option key={a} value={a}>{a}</option>)}
                </select>
                <input className={inp} placeholder="WhatsApp (51931...)" value={ed.phone} onChange={(e) => setEd({ ...ed, phone: e.target.value })} />
              </div>
              <button className="btn-fire w-full py-2 rounded-xl text-xs">Guardar</button>
            </form>
          )}

          {p.phone && (
            <a target="_blank" rel="noreferrer" href={`https://wa.me/${p.phone.replace(/\D/g, '')}`} className="block text-center py-2 mt-3 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold transition">Escribirle por WhatsApp 💬</a>
          )}
        </div>
      </div>

      <div className="grid grid-cols-4 gap-2 text-center">
        {[['G / P', `${p.matchesWon || 0}/${p.matchesLost || 0}`], ['Efic.', `${winRate}%`], ['Sets', p.setsWon || 0], ['MVP', `⭐${p.mvpCount || 0}`]].map(([l, v]) => (
          <div key={l} className={card + ' !py-2.5 !px-1'}>
            <div className="num text-2xl text-amber-400">{v}</div>
            <div className="text-[10px] text-slate-500 mt-1">{l}</div>
          </div>
        ))}
      </div>

      <AttendanceCard id={p.id} events={events || []} isAdmin={isAdmin} />

      <ProfileHistory id={p.id} players={players} />

      <div className={card + ' space-y-1.5'}>
        <p className="text-xs font-bold text-amber-400 mb-1">Fundamentos</p>
        {SK.map((k) => {
          const v = skv(p.skills, k);
          return (
            <div key={k} className="flex items-center gap-2 text-[11px]">
              <span className="w-24 capitalize text-slate-400">{skLabel(k)}</span>
              <div className="flex-1 h-2 rounded-full bg-slate-800 overflow-hidden"><div className="bar h-full rounded-full" style={{ width: (v / 5) * 100 + '%' }} /></div>
              <b className="w-5 text-right text-amber-400 font-mono">{v}</b>
            </div>
          );
        })}
      </div>

      <p className="text-xs font-bold text-amber-400 pt-1">🧱 Muro de {p.nickname} ({list.length})</p>
      <PostComposer me={me} isAdmin={isAdmin} wallOwner={p.id} placeholder={mine ? `¿Qué quieres compartir en tu muro, ${me.nickname}?` : `Escribe algo en el muro de ${p.nickname}...`} />
      {list.length === 0 && <p className="text-center text-xs text-slate-500 py-6">{mine ? 'Tu muro está vacío. ¡Publica tu primera foto!' : `Sé el primero en escribirle a ${p.nickname}.`}</p>}
      {list.map((x) => <PostCard key={x.id} p={x} me={me} players={players} isAdmin={isAdmin} onProfile={onProfile} />)}
    </div>
  );
}

// ===== MENSAJES PRIVADOS =====
function useMsgs(uid) {
  const [d, setD] = useState([]);
  useEffect(() => db.collection('messages').where('participants', 'array-contains', uid).onSnapshot(
    (s) => setD(s.docs.map((x) => ({ id: x.id, ...x.data() }))),
    (e) => { console.error(e); setD([]); }
  ), [uid]);
  return d;
}
const readKey = (uid) => 'af-read-' + uid;
const getRead = (uid) => { try { return JSON.parse(localStorage.getItem(readKey(uid)) || '{}'); } catch (e) { return {}; } };

function Messages({ me, players, msgs, peer, setPeer, readMap, markRead, onProfile }) {
  const [q, setQ] = useState('');
  const [txt, setTxt] = useState('');
  const [img, setImg] = useState(null);
  const [big, setBig] = useState(null);
  const endRef = React.useRef(null);
  const pickImg = async (e) => {
    const f = e.target.files && e.target.files[0];
    e.target.value = '';
    if (!f) return;
    if (!f.type.startsWith('image/')) return alert('Por ahora solo se pueden enviar fotos.');
    try { setImg(await fileToDataUrl(f)); }
    catch (x) { alert('No se pudo cargar esa foto. Prueba con otra.'); }
  };

  const other = (m) => (m.from === me.id ? m.to : m.from);
  const thread = peer ? msgs.filter((m) => other(m) === peer).sort((a, b) => a.createdAt - b.createdAt) : [];

  useEffect(() => {
    if (!peer) return;
    markRead(peer);
    if (endRef.current) endRef.current.scrollIntoView({ block: 'end' });
  }, [peer, thread.length]);

  const send = async (e) => {
    e.preventDefault();
    const t = txt.trim(), im = img;
    if ((!t && !im) || !peer) return;
    setTxt(''); setImg(null);
    try {
      await db.collection('messages').add({ participants: [me.id, peer], from: me.id, to: peer, text: t.slice(0, 1000), ...(im ? { image: im } : {}), createdAt: Date.now() });
    } catch (x) { setTxt(t); setImg(im); alert('No se pudo enviar el mensaje. ¿Pegaste las reglas nuevas en Firebase?'); }
  };

  // ---- Conversación abierta ----
  if (peer) {
    const pl = players.find((x) => x.id === peer);
    return (
      <div className={card + ' !p-0 overflow-hidden flex flex-col'} style={{ height: 'calc(100vh - 190px)', minHeight: 360 }}>
        <div className="p-3 border-b border-slate-800 flex items-center gap-2.5">
          <button onClick={() => setPeer(null)} className="w-8 h-8 rounded-full bg-slate-800 text-slate-300 text-sm shrink-0">←</button>
          <span onClick={() => pl && onProfile(pl.id)} className="cursor-pointer"><Av p={pl} size="w-9 h-9" text="text-xl" /></span>
          <div className="min-w-0">
            <b onClick={() => pl && onProfile(pl.id)} className="text-sm text-slate-100 cursor-pointer hover:underline">{pl ? pl.nickname : 'Jugador'}</b>
            <p className="text-[10px] text-slate-500 truncate">{pl ? pl.name : ''}</p>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-3 space-y-1.5">
          {thread.length === 0 && <p className="text-center text-xs text-slate-500 py-10">Aún no hay mensajes. ¡Rompe el hielo! 🏐</p>}
          {thread.map((m) => {
            const mineM = m.from === me.id;
            return (
              <div key={m.id} className={'flex ' + (mineM ? 'justify-end' : 'justify-start')}>
                <div className={'max-w-[80%] rounded-2xl px-3 py-1.5 text-sm ' + (mineM ? 'btn-fire rounded-br-md' : 'bg-slate-800 text-slate-100 rounded-bl-md')}>
                  {m.image && <img src={m.image} alt="" loading="lazy" onClick={() => setBig(m.image)} className="rounded-xl max-h-64 w-full object-cover mb-1 cursor-pointer" />}
                  {m.text && <Linkify text={m.text} className="whitespace-pre-line break-words" />}
                  <p className="text-[9px] mt-0.5 text-right" style={{ opacity: .65 }}>{ago(m.createdAt)}</p>
                </div>
              </div>
            );
          })}
          <div ref={endRef} />
        </div>

        {img && (
          <div className="px-2.5 pt-2.5 border-t border-slate-800 relative">
            <img src={img} alt="" className="rounded-xl max-h-32 object-cover" />
            <button type="button" onClick={() => setImg(null)} className="absolute top-3.5 left-4 w-6 h-6 rounded-full bg-black/70 text-white text-xs">✕</button>
          </div>
        )}
        <form onSubmit={send} className="p-2.5 border-t border-slate-800 flex gap-2 items-center">
          <label className="w-10 h-10 shrink-0 rounded-xl bg-slate-800 hover:bg-slate-700 flex items-center justify-center cursor-pointer transition" title="Enviar foto">
            📷
            <input type="file" accept="image/*" className="hidden" onChange={pickImg} />
          </label>
          <input className={inp} placeholder="Escribe un mensaje..." value={txt} maxLength={1000} onChange={(e) => setTxt(e.target.value)} />
          <button disabled={!txt.trim() && !img} className="btn-fire px-4 h-10 rounded-xl text-sm disabled:opacity-40">Enviar</button>
        </form>
        {big && (
          <div className="fixed inset-0 z-[60] bg-black/90 flex items-center justify-center p-3" onClick={() => setBig(null)}>
            <img src={big} alt="" className="max-w-full max-h-full rounded-xl" />
            <button className="absolute top-4 right-4 w-9 h-9 rounded-full bg-black/70 text-white">✕</button>
          </div>
        )}
      </div>
    );
  }

  // ---- Bandeja de entrada ----
  const last = {};
  msgs.forEach((m) => { const o = other(m); if (!last[o] || m.createdAt > last[o].createdAt) last[o] = m; });
  const convs = Object.keys(last).sort((a, b) => last[b].createdAt - last[a].createdAt);
  const people = players.filter((x) => x.id !== me.id && ((x.name || '') + (x.nickname || '')).toLowerCase().includes(q.toLowerCase()));

  return (
    <div className="space-y-3">
      <div className={card + ' !p-0 overflow-hidden'}>
        <div className="p-3 border-b border-slate-800 text-xs font-bold text-amber-400">💬 Mis mensajes</div>
        {convs.length === 0 && <p className="text-center text-xs text-slate-500 py-8 px-4">Todavía no tienes conversaciones. Elige a un jugador abajo y escríbele.</p>}
        <div className="divide-y divide-slate-800/80">
          {convs.map((id) => {
            const m = last[id], pl = players.find((x) => x.id === id);
            const unread = m.to === me.id && m.createdAt > (readMap[id] || 0);
            return (
              <button key={id} onClick={() => setPeer(id)} className="w-full p-3 flex items-center gap-2.5 text-left hover:bg-slate-800/30 transition">
                <Av p={pl} size="w-10 h-10" text="text-2xl" />
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-center gap-2">
                    <b className={'text-sm truncate ' + (unread ? 'text-slate-100' : 'text-slate-300')}>{pl ? pl.nickname : 'Jugador'}</b>
                    <span className="text-[10px] text-slate-500 shrink-0">{ago(m.createdAt)}</span>
                  </div>
                  <p className={'text-xs truncate ' + (unread ? 'text-slate-200 font-bold' : 'text-slate-500')}>{m.from === me.id ? 'Tú: ' : ''}{m.text || '📷 Foto'}</p>
                </div>
                {unread && <span className="w-2.5 h-2.5 rounded-full bg-amber-500 shrink-0" />}
              </button>
            );
          })}
        </div>
      </div>

      <div className={card + ' space-y-2.5'}>
        <p className="text-xs font-bold text-amber-400">✉️ Nuevo mensaje</p>
        <input className={inp} placeholder="Buscar jugador..." value={q} onChange={(e) => setQ(e.target.value)} />
        <div className="max-h-64 overflow-y-auto divide-y divide-slate-800/80">
          {people.map((x) => (
            <button key={x.id} onClick={() => setPeer(x.id)} className="w-full py-2 flex items-center gap-2.5 text-left hover:bg-slate-800/30 transition">
              <Av p={x} size="w-8 h-8" text="text-xl" />
              <div className="min-w-0">
                <b className="text-sm text-slate-200">{x.nickname}</b>
                <p className="text-[10px] text-slate-500 truncate">{x.name}</p>
              </div>
            </button>
          ))}
          {people.length === 0 && <p className="text-xs text-slate-500 py-3">No se encontró a nadie.</p>}
        </div>
      </div>
    </div>
  );
}

// ===== Polos del equipo: vista previa y lista de interesados =====
const SIZES = ['S', 'M', 'L', 'XL'];
function Polos() {
  return (
    <div className="space-y-4 enter">
      <div className={card + ' text-center py-14 space-y-3'}>
        <div className="text-6xl">👕</div>
        <b className="text-xl block">Polos IceFire</b>
        <span className="inline-block px-3 py-1 rounded-full bg-amber-500/20 text-amber-400 border border-amber-500/30 text-xs font-black tracking-wide">🔥 PRÓXIMAMENTE</span>
      </div>
    </div>
  );
}

const ICONS = {
  feed: <path d="M3 11l9-8 9 8v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z" />,
  rank: <path d="M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0zM17 5h3v2a3 3 0 0 1-3 3M7 5H4v2a3 3 0 0 0 3 3" />,
  roster: <><circle cx="9" cy="8" r="3.5" /><path d="M2.5 20a6.5 6.5 0 0 1 13 0M16 4.5a3.5 3.5 0 0 1 0 7M18 14.5a6.5 6.5 0 0 1 3.5 5.5" /></>,
  teams: <path d="M16 3h5v5M4 20 21 3M21 16v5h-5M15 15l6 6M4 4l5 5" />,
  events: <><rect x="3" y="5" width="18" height="16" rx="2" /><path d="M16 3v4M8 3v4M3 10h18" /></>,
  chat: <path d="M21 12a8 8 0 0 1-11.5 7.2L4 21l1.8-5.3A8 8 0 1 1 21 12z" />,
  polos: <path d="M8 3 3 6l2 4 3-1v12h8V9l3 1 2-4-5-3a4 4 0 0 1-8 0z" />,
  marcador: <><rect x="3" y="4" width="18" height="13" rx="2" /><path d="M12 4v13M8 21h8M12 17v4" /></>,
  admin: <path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z" />
};

function VerifyBanner({ user }) {
  const [sent, setSent] = useState(false);
  const [err, setErr] = useState('');
  const send = async () => {
    setErr('');
    try { await user.sendEmailVerification(); setSent(true); }
    catch (x) { setErr('No se pudo enviar. Espera un momento e inténtalo otra vez.'); }
  };
  const done = async () => {
    await user.reload();
    await user.getIdToken(true);
    location.reload();
  };
  return (
    <div className={card + ' border-amber-500/40 space-y-2'}>
      <p className="text-sm font-bold text-amber-400">🔐 Verifica tu correo para activar el modo Admin</p>
      <p className="text-[11px] text-slate-400">Es una medida de seguridad: así nadie puede hacerse pasar por ti.</p>
      {err && <p className="text-xs text-rose-400">{err}</p>}
      <div className="flex gap-2">
        <button onClick={send} className="btn-fire px-3 py-1.5 rounded-xl text-xs">{sent ? 'Correo enviado, revisa tu bandeja' : 'Enviar correo de verificación'}</button>
        <button onClick={done} className="px-3 py-1.5 rounded-xl bg-slate-800 text-slate-200 text-xs font-bold">Ya verifiqué</button>
      </div>
    </div>
  );
}

// ===== COMPONENTE PRINCIPAL CON NAVEGACIÓN Y ROLES =====
function Main({ user }) {
  const playersRaw = useCol('players');
  // Antes existía "Líbero": ahora todos son "Defensa"
  const players = useMemo(() => (playersRaw ? playersRaw.map((p) => (p.position === 'libero' ? { ...p, position: 'defensa' } : p)) : playersRaw), [playersRaw]);
  const posts = useCol('posts', (c) => c.orderBy('createdAt', 'desc').limit(150));
  const events = useCol('events');
  const trisCol = useCol('triangulars', (c) => c.orderBy('createdAt', 'desc').limit(1));
  const tri = trisCol && trisCol[0] && trisCol[0].active ? trisCol[0] : null;
  const msgs = useMsgs(user.uid);
  const [readMap, setReadMap] = useState(() => getRead(user.uid));
  const [peer, setPeer] = useState(null);
  const markRead = (pid) => {
    const m = { ...getRead(user.uid), [pid]: Date.now() };
    try { localStorage.setItem(readKey(user.uid), JSON.stringify(m)); } catch (e) {}
    setReadMap(m);
  };
  const [tab, setTab] = useState(() => (evHash() ? 'events' : 'feed'));
  const [modal, setModal] = useState(null);
  const [focusEv, setFocusEv] = useState(evHash);
  const [teamEv, setTeamEv] = useState(null);
  const [profile, setProfileId] = useState(hashId);
  const setProfile = (id) => { location.hash = id ? '#/p/' + id : ''; };
  useEffect(() => {
    const f = () => { setProfileId(hashId()); const e = evHash(); setFocusEv(e); if (e) setTab('events'); else window.scrollTo({ top: 0 }); };
    window.addEventListener('hashchange', f);
    return () => window.removeEventListener('hashchange', f);
  }, []);
  const [theme, setTheme] = useState(document.documentElement.dataset.theme || 'light');
  const toggleTheme = () => {
    const t = theme === 'dark' ? 'light' : 'dark';
    document.documentElement.dataset.theme = t;
    try { localStorage.setItem('af-theme', t); } catch (e) {}
    setTheme(t);
  };

  if (players === null || posts === null || events === null) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-3">
        <img src={LOGO_ICON} alt="" className="af-mark af-pulse" style={{ width: 44, height: 44, objectFit: 'cover', background: 'none' }} />
        <p className="text-xs text-slate-400 font-bold">Cargando IceFire…</p>
      </div>
    );
  }

  const me = players.find((p) => p.id === user.uid);
  if (!me) return <Auth user={user} />;

  // Validación de Administradores: Whitelist de correos o campo isAdmin en BD
  const userEmail = (user.email || me.email || '').toLowerCase().trim();
  const isOwner = ADMIN_EMAILS.includes(userEmail) && user.emailVerified === true;
  const needsVerify = ADMIN_EMAILS.includes(userEmail) && !user.emailVerified;
  const isAdmin = isOwner || me.isAdmin === true;

  const startTri = async (teams) => {
    if (tri && !confirm('Ya hay un triangular en curso. ¿Reemplazarlo por este?')) return;
    try {
      if (tri) await db.collection('triangulars').doc(tri.id).update({ active: false });
      await db.collection('triangulars').add({ active: true, teams, cur: [0, 1], wait: 2, consec: [0, 0, 0], max: 2, games: [], createdBy: me.id, createdAt: Date.now() });
    } catch (e) { alert('No se pudo iniciar el triangular: ' + e.message); }
  };

  const baseTabs = [
    ['feed', 'Muro'],
    ['rank', 'Ranking'],
    ['roster', 'Plantel'],
    ['teams', 'Equipos'],
    ['events', 'Pichangas'],
    ['polos', 'Polos'],
    ['chat', 'Chat']
  ];
  const unread = msgs.filter((m) => m.to === me.id && m.createdAt > (readMap[m.from] || 0)).length;
  const tabs = isAdmin ? [...baseTabs, ['marcador', 'Marcador'], ['admin', 'Admin']] : baseTabs;

  return (
    <div className="relative z-10 max-w-3xl mx-auto p-3 pb-28 space-y-4">
      {/* Cabecera */}
      <header className="hdr sticky top-0 z-40 -mx-3 -mt-3 px-3 py-2.5 flex flex-wrap items-center justify-between gap-x-2 gap-y-1.5">
        <div className="flex items-center gap-2 shrink-0">
          <img src={LOGO_ICON} alt="" className="af-mark" style={{ objectFit: 'cover', background: 'none' }} /><span className="logo text-2xl">Ice<span className="fire">Fire</span></span>
          {isAdmin && <span className="hidden sm:inline whitespace-nowrap text-[10px] font-bold px-1.5 py-0.5 rounded bg-amber-500/15 text-amber-400 border border-amber-500/30">Admin</span>}
        </div>
        <div className="flex items-center gap-1.5 ml-auto">
          {isAdmin && (
            <button onClick={() => setModal({})} title="Registrar partido" className="btn-fire px-3 py-1.5 rounded-xl text-xs flex items-center gap-1 whitespace-nowrap">
              <span>🔥</span>
              <span className="hidden sm:inline">Registrar partido</span>
            </button>
          )}
          {WA_GROUP_LINK && (
            <a href={WA_GROUP_LINK} target="_blank" rel="noreferrer" title="Grupo de WhatsApp" className="w-9 h-9 rounded-full bg-emerald-500/15 border border-emerald-500/40 text-base flex items-center justify-center">💬</a>
          )}
          {WA_COMMUNITY_LINK && (
            <a href={WA_COMMUNITY_LINK} target="_blank" rel="noreferrer" title="Comunidad de WhatsApp" className="w-9 h-9 rounded-full bg-emerald-500/15 border border-emerald-500/40 text-base flex items-center justify-center">🌐</a>
          )}
          <button title={theme === 'dark' ? 'Modo claro' : 'Modo oscuro'} onClick={toggleTheme} className="w-9 h-9 rounded-full bg-slate-800 text-base flex items-center justify-center">
            {theme === 'dark' ? '☀️' : '🌙'}
          </button>
          <button title="Mi perfil" onClick={() => setProfile(me.id)} className="w-9 h-9 rounded-full bg-slate-900 border-2 border-amber-500 text-base flex items-center justify-center overflow-hidden">
            {me.photo ? <img src={me.photo} alt="" className="w-full h-full object-cover" /> : me.avatar}
          </button>
        </div>
      </header>

      {needsVerify && <VerifyBanner user={user} />}

      {/* Contenedor de Vistas */}
      <main className="enter">
        {profile && <ProfilePage id={profile} me={me} players={players} posts={posts} isAdmin={isAdmin} events={events} onProfile={setProfile} onClose={() => setProfile(null)} onMessage={(id) => { setProfile(null); setPeer(id); setTab('chat'); }} />}
        {!profile && tab === 'feed' && <Feed me={me} posts={posts} players={players} isAdmin={isAdmin} onProfile={setProfile} events={events} onGo={() => setTab('events')} onTab={(t) => { setTab(t); window.scrollTo({ top: 0 }); }} />}
        {!profile && tab === 'rank' && <Ranking players={players} onProfile={setProfile} isAdmin={isAdmin} />}
        {!profile && tab === 'roster' && <Roster players={players} onProfile={setProfile} />}
        {!profile && tab === 'teams' && <><Triangular tri={tri} players={players} isAdmin={isAdmin} /><Teams key={teamEv || 'x'} players={players} events={events} initialEv={teamEv} isAdmin={isAdmin} onRegister={(a, b) => setModal({ a, b })} onStartTri={startTri} /></>}
        {!profile && tab === 'marcador' && isAdmin && <Marcador db={db} isAdmin={isAdmin} />}
        {!profile && tab === 'polos' && <Polos me={me} isAdmin={isAdmin} />}
        {!profile && tab === 'events' && <Events me={me} events={events} players={players} isAdmin={isAdmin} focusId={focusEv} onProfile={setProfile} onTeams={(id) => { setTeamEv(id); setTab('teams'); window.scrollTo({ top: 0 }); }} />}
        {!profile && tab === 'chat' && <Messages me={me} players={players} msgs={msgs} peer={peer} setPeer={setPeer} readMap={readMap} markRead={markRead} onProfile={setProfile} />}
        {!profile && tab === 'admin' && isAdmin && <AdminPanel me={me} players={players} />}
      </main>

      {/* Modal de Marcador Oficial */}
      {/* Barra de navegación inferior */}
      <nav className="tabbar fixed bottom-0 inset-x-0 z-40">
        <div className="max-w-3xl mx-auto flex">
          {tabs.map(([id, l]) => (
            <button key={id} onClick={() => { if (profile) setProfile(null); else if (evHash()) location.hash = ''; setTab(id); window.scrollTo({ top: 0 }); }} className={`af-tab relative flex-1 flex flex-col items-center gap-0.5 pt-2 pb-1.5 text-[10px] font-bold ${tab === id ? 'af-tab-on text-amber-400' : 'text-slate-400'}`}>
              <svg className="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{ICONS[id]}</svg>
              {id === 'chat' && unread > 0 && <span className="absolute top-1 right-1/4 min-w-[16px] h-4 px-1 rounded-full bg-rose-500 text-white text-[9px] font-black flex items-center justify-center">{unread > 9 ? '9+' : unread}</span>}
              <span>{l}</span>
            </button>
          ))}
        </div>
      </nav>

      {modal && <MatchModal players={players} init={modal} onClose={() => setModal(null)} />}
    </div>
  );
}

// ===== ROOT APP =====
function App() {
  const [user, setUser] = useState(undefined);
  const [reg, setReg] = useState(false);

  useEffect(() => auth.onAuthStateChanged((u) => setUser(u)), []);

  if (user === undefined || (user && reg)) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-3">
        <img src={LOGO_ICON} alt="" className="af-mark af-pulse" style={{ width: 44, height: 44, objectFit: 'cover', background: 'none' }} />
        <p className="text-xs text-slate-400 font-bold">Iniciando…</p>
      </div>
    );
  }

  if (!user) return <Auth setReg={setReg} />;
  return <Main user={user} />;
}

const Embers = () => (
  <div className="embers" aria-hidden="true">
    {[6, 18, 30, 42, 55, 67, 78, 90, 12, 48].map((l, i) => (
      <i key={i} style={{ left: l + '%', animationDelay: i * 1.3 + 's', animationDuration: 7 + (i % 4) * 2 + 's' }} />
    ))}
  </div>
);

ReactDOM.createRoot(document.getElementById('root')).render(
  <>
    <App />
  </>
);
